TN.defSec("renal-genitourinary",{"acute-kidney-injury":{"id":"acute-kidney-injury","variants":[{"id":"aki-prerenal","o":{"I":[{"t":"Bedside ultrasound of the inferior vena cava (volume status and fluid responsiveness); renal ultrasound if obstruction suspected"}],"L":[{"t":"Urinalysis and urine sediment, urinary sodium and creatinine, urine osmolality (fractional excretion of sodium), serum electrolytes"}],"S":[{"t":"Isotonic fluids (normal saline or Lactated Ringer's solution) for volume resuscitation, guided by volume status and urine output","fl":[{"k":"ci","v":"avoid if heart failure or pulmonary edema; cardiac failure: optimize cardiac output"}]}],"T":[{"t":"Foley catheter placement with close monitoring of urine output"},{"t":"Avoid nephrotoxic medications and intravenous contrast","fl":[{"k":"ci","v":"avoid"}]}],"Co":[{"t":"Admission (new-onset renal failure usually requires admission)"}]},"name":"Prerenal AKI (hypovolemia), stable","level":"II","imp":"Acute kidney injury, prerenal","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"PA","sc":"مردی ۷۲ ساله با اسهال و استفراغ ۳ روزه، تاکی‌کاردی و کراتینین بالا.","why":"بیشتر موارد پیش‌کلیوی‌اند؛ مایع ایزوتونیک با راهنمایی وضعیت حجم و پایش ادرار؛ ECG برای هیپرکالمی."},{"id":"aki-intrinsic","o":{"I":[{"t":"Renal ultrasound (hydronephrosis); color-flow Doppler for renal perfusion if large-vessel cause suspected"}],"L":[{"t":"Urinalysis and sediment, urinary sodium and creatinine, urine osmolality, serum potassium (hyperkalemia)"}],"S":[{"t":"Restore adequate circulating volume first with isotonic crystalloid, guided by volume status","fl":[{"k":"ci","v":"fluid restriction may be required; avoid in pulmonary edema"}]}],"T":[{"t":"Vasopressor support with norepinephrine or dopamine as a temporizing measure for mean arterial pressure in shock"},{"t":"Foley catheter with close monitoring of urine output"},{"t":"Caution with renally excreted drugs (digoxin, magnesium, sedatives and narcotics) and intravenous contrast","fl":[{"k":"renal","v":"therapeutic doses may accumulate to excess"}]}],"Co":[{"t":"Nephrology as soon as possible if urgent dialysis is considered (BUN > 100 mg/dL or creatinine > 10 mg/dL, cardiac instability, intractable volume overload, hyperkalemia, uremic encephalopathy, pericarditis or bleeding diathesis)"},{"t":"Intensive care unit admission; transfer if nephrology and dialysis are not available"}]},"name":"Intrinsic AKI (ischemic / nephrotoxic) or uremic complications","level":"I","imp":"Acute kidney injury, intrinsic (ATN / nephrotoxic)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"زنی ۶۸ ساله پس از شوک سپتیک و مصرف داروی نفروتوکسیک با اولیگوری، پتاسیم 6.8 و تغییرات ECG.","why":"هیپرکالمی و اضافه حجم تهدیدکننده‌اند؛ حجم را ابتدا برگردان؛ دیالیز در موارد شدید."},{"id":"aki-postrenal","o":{"I":[{"t":"Bladder scan or bedside ultrasound (full bladder); renal ultrasound (hydronephrosis)"}],"L":[{"t":"Urinalysis, serum electrolytes"}],"T":[{"t":"Foley catheter for prostatic obstruction; drain urine completely and rapidly (no data to support intermittent clamping)"},{"t":"Percutaneous nephrostomy for ureteral occlusion until definitive surgery"},{"t":"With chronic urinary retention monitor urine output closely for postobstructive diuresis; replace fluid as needed"}],"Co":[{"t":"Emergency urologic consultation if no urine on initial bladder catheterization and the bladder is full"}]},"name":"Postrenal AKI (obstruction / anuria)","level":"II","imp":"Acute kidney injury, postrenal (obstruction)","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مردی ۷۸ ساله با آنوری، درد زیر شکم و مثانه پر.","why":"انسداد علت اصلی آنوری حاد است؛ درناژ فوری ادرار."}],"ch":"50","name":"Acute kidney injury (prerenal, intrinsic, postrenal)","name_fa":"آسیب حاد کلیه (پیش‌کلیوی، ذاتی، پس‌کلیوی)","cc":["urinary-symptoms","metabolic","altered-mental-status"],"keywords":"acute kidney injury, acute renal failure, ATN, prerenal, postrenal, fractional excretion of sodium, hyperkalemia, dialysis, Foley, nephrostomy, نارسایی حاد کلیه","status":"draft","features":["تظاهرات بسته به علت: هیپوولمی، داروهای نفروتوکسیک، مشکلات آناتومیک مجاری ادراری؛ علل قلبی، عروقی، ترومبوتیک، گلومرولی و توبولی","تجمع مواد ازته و اختلال الکترولیت؛ با پیشرفت اورمی: اضافه حجم، فشار بالا، ادم ریه، تغییر هوشیاری یا علائم عصبی، تهوع و استفراغ، مشکلات استخوان/مفصل، کم‌خونی و استعداد عفونت (علت اصلی مرگ)","پیش‌کلیوی (70٪ موارد اکتسابی از جامعه): کاهش پرفیوژن (استفراغ/اسهال، دیورتیک و داروهای ضدفشار، کاهش دریافت، سکوئستراسیون مایع در سیروز/پانکراتیت/سوختگی/شوک سپتیک، خونریزی، کاهش برون‌ده قلبی)","ذاتی: ایسکمیک (ATN، شایع‌ترین علت نارسایی بیمارستانی) و نفروتوکسین‌ها (دومین علت شایع)؛ بیماری‌های گلومرولی و توبولواینترستیشیال","پس‌کلیوی: عمدتاً مردان سالمند با انسداد پروستات؛ تنگی مجرا؛ از دست رفتن دائمی عملکرد طی 10 تا 14 روز با انسداد کامل و بدتر با UTI","آنالیز ادرار و رسوب: کست گرانولار در ATN؛ کست RBC و آلبومین در گلومرولونفریت/هیپرتانسیون بدخیم؛ کست WBC در نفریت بینابینی و پیلونفریت؛ کریستال در سنگ و برخی داروها (سولفا، اتیلن گلیکول، کنتراست)","FENa < 1٪ و اسمولالیته ادرار > 500: پیش‌کلیوی؛ FENa > 1٪ و اسمولالیته < 350: ذاتی","سونوگرافی کلیه روش انتخابی در شک به انسداد/هیدرونفروز؛ سونوگرافی بالین IVC برای وضعیت حجم و پاسخ به مایع"],"ddx":[{"n":"Hyperkalemia / uremic complications |","cm":1},{"n":"Postrenal obstruction (prostatic, stone, stricture) |","cm":1},{"n":"Rhabdomyolysis |","cm":1},{"n":"Prerenal azotemia (hypovolemia, cardiac failure) |"},{"n":"Nephrotoxin or contrast-induced AKI |"},{"n":"Glomerulonephritis / interstitial nephritis / HUS / TTP |"}],"redflags":["هیپرکالمی با تغییرات ECG، ادم ریه یا اضافه حجم مقاوم، آنسفالوپاتی/پریکاردیت/خونریزی اورمیک، BUN > 100 یا کراتینین > 10، آنوری"],"guide":"# هدف ED\nدرمان علت زمینه‌ای و اصلاح اختلال مایع و الکترولیت؛ جلوگیری از آسیب بیشتر کلیه و حمایت؛ پایش دقیق ادرار (در نظر گرفتن Foley)؛ ECG برای تغییرات هیپرکالمی؛ پتاسیم، کراتینین و BUN.\n\n# پیش‌کلیوی\nمایع ایزوتونیک (نرمال سالین یا Ringer لاکتات) برای احیای حجم. اگر علت نارسایی قلب است برون‌ده قلبی را بهینه کن؛ کاهش حجم داخل عروقی (دیورتیک) ممکن است مناسب باشد؛ اکوی بالین و سونوگرافی IVC کمک می‌کند.\n\n# ذاتی\nاول حجم گردش خون را برگردان (هیپوولمی همه اشکال را بدتر می‌کند)؛ پرهیز از داروهای نفروتوکسیک و کنتراست وریدی؛ وازوپرسور (norepinephrine یا dopamine) به‌عنوان اقدام موقت برای MAP در شوک؛ احتیاط در داروهای دفع‌شونده از کلیه (دیگوکسین، منیزیم، آرام‌بخش‌ها و مخدرها) و محدودیت مایع در صورت نیاز.\n\n# پس‌کلیوی\nدرناژ ادرار: Foley برای هیپرتروفی پروستات (تخلیه کامل و سریع؛ شواهدی برای کلامپ متناوب نیست)؛ نفروستومی از راه پوست برای انسداد حالب؛ در آنوری حاد در صورت نبود ادرار با کاتتر و مثانه پر: مشاوره اورولوژی اورژانس؛ انسداد مزمن: دیورز پس از رفع انسداد (پایش ادرار و جایگزینی مایع).\n\n# دیالیز\nبا نفرولوژیست مشورت؛ معمولاً BUN > 100 یا کراتینین > 10؛ هیپرکالمی شدید، اضافه حجم مقاوم، اورمی (آنسفالوپاتی، پریکاردیت، دیاتز خونریزی) یا بی‌ثباتی قلبی (اسیدوز متابولیک و هیپرکالمی). بیمار جدید معمولاً بستری (اغلب ICU).","pearls":["IVC سونوگرافی: کلاپس دمی = پیش‌کلیوی؛ اتساع بدون تغییر = اضافه حجم.","کاتتر اورتر را کامل و سریع تخلیه کن."],"section":"renal-genitourinary","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 50: Acute Kidney Injury, pp. 287–291"},"rhabdomyolysis":{"id":"rhabdomyolysis","variants":[{"id":"rhabdo-exertional-mild","o":{"L":[{"t":"Creatine kinase, urinalysis (urine dipstick positive for blood without red blood cells on microscopy suggests myoglobinuria), serum calcium, phosphorus, uric acid"}],"S":[{"t":"Oral or IV rehydration","fl":[{"k":"note","v":"rate not given for this group"}]}],"Co":[{"t":"Observe in the ED and release if no heat stress, dehydration, trauma or comorbidity"}]},"name":"Exertional rhabdomyolysis, healthy, no comorbidities","level":"III","imp":"Exertional rhabdomyolysis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"مردی ۲۵ ساله پس از مسابقه ماراتن با درد عضلانی و ادرار تیره؛ CK 8 برابر نرمال.","why":"بیمار سالم بدون عارضه می‌تواند با مایع خوراکی یا وریدی تحت نظر و مرخص شود."},{"id":"rhabdo-moderate-severe","o":{"L":[{"t":"Serial urine pH, electrolytes, creatine kinase, calcium, phosphorus, uric acid, BUN and creatinine; PT, PTT, fibrin split products, fibrinogen (disseminated intravascular coagulation screen)"}],"S":[{"t":"Aggressive IV rehydration for 24 to 72 hours: rapid correction of the fluid deficit with IV crystalloids followed by 2.5 mL/kg/h, goal urine output at least 2 mL/kg/h (or titrate to 200 to 300 mL of urine per hour)","fl":[{"k":"ci","v":"hemodynamic monitoring in heart disease, comorbid conditions, preexisting renal disease or elderly to avoid fluid overload"}]}],"T":[{"t":"Urinary catheter to monitor urine output"},{"t":"Hyperkalemia: ion-exchange resin (sodium polystyrene sulfonate); calcium for hyperkalemia-induced cardiotoxicity or profound signs of hypocalcemia"},{"t":"Phosphate binders orally if phosphate > 7 mg/dL"},{"t":"If bicarbonate is given: isotonic solution, avoid metabolic alkalosis or hypokalemia (not evidence based)"},{"t":"Avoid NSAIDs","fl":[{"k":"ci","v":"prostaglandin inhibitors (vasoconstriction of the kidney)"}]},{"t":"Treat the underlying cause"}],"Co":[{"t":"Admit to a monitored bed; nephrology for dialysis in hyperkalemia unresponsive to therapy"}]},"name":"Rhabdomyolysis with complications or comorbidity","level":"I","imp":"Rhabdomyolysis with possible acute renal failure / hyperkalemia","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"none","sc":"مردی ۵۵ ساله مبتلا به سوءمصرف الکل پس از افتادن طولانی روی زمین با CK بالای 50000، پتاسیم 6.2 و کراتینین بالا.","why":"CK بالا و عارضه: مایع تهاجمی ۲۴ تا ۷۲ ساعت، پایش الکترولیت و قلبی، بستری در تخت مانیتور."}],"ch":"51","name":"Rhabdomyolysis","name_fa":"رابدومیولیز","cc":["weakness","joint-limb-pain","urinary-symptoms"],"keywords":"rhabdomyolysis, creatine kinase, myoglobinuria, dark urine, crush, statin, compartment syndrome, hyperkalemia, رابدومیولیز","status":"draft","features":["تخریب عضله اسکلتی؛ علل شایع در بزرگسالان: الکل و مواد سوءمصرف، سپس داروها (استاتین، آنتی‌سایکوتیک...)، بیماری‌های عضلانی، تروما، NMS، تشنج، بی‌حرکتی، عفونت، فعالیت شدید و گرمازدگی؛ در بیش از نیمی چند علت","در کودکان کمتر شایع و خوش‌خیم‌تر","حاد: میالژی، سفتی، ضعف، بی‌حالی، تب خفیف و ادرار تیره (قهوه‌ای)؛ تهوع، استفراغ، درد شکم و تاکی‌کاردی در شدید؛ علائم عضلانی فقط در نیمی","ممکن است بدون علامت و معاینه نرمال باشد؛ تشخیص از شرح حال، CK بالا یا ادرار تیره","عوارض: نارسایی حاد کلیه، هیپرکالمی، هیپرفسفاتمی، هیپراوریسمی، هیپوکلسمی (اوایل)، هیپرکلسمی و هیپوفسفاتمی (دیررس)، DIC، سندرم کمپارتمان و نوروپاتی محیطی","CK ≥ 5 برابر حد بالای نرمال بدون آسیب قلبی/مغزی؛ میوگلوبینوری: دیپ‌استیک مثبت برای خون با RBC منفی در میکروسکوپ؛ نبود میوگلوبینوری رد نمی‌کند (ظرف 1 تا 6 ساعت نرمال می‌شود)"],"ddx":[{"n":"Hyperkalemia / acute renal failure |","cm":1},{"n":"Compartment syndrome |","cm":1},{"n":"Neuroleptic malignant syndrome / heat stroke |","cm":1},{"n":"Acute myopathy / periodic paralysis |"},{"n":"Polymyositis / dermatomyositis |"},{"n":"Guillain-Barre syndrome |"}],"redflags":["هیپرکالمی (شدیدترین 12 تا 36 ساعت اول)، آنوری/نارسایی کلیه، DIC، سندرم کمپارتمان"],"guide":"مایع وریدی تهاجمی ۲۴ تا ۷۲ ساعت: اصلاح سریع کمبود با کریستالوئید سپس ۲.۵ mL/kg/h با هدف ادرار حداقل ۲ mL/kg/h؛ یا تنظیم برای ۲۰۰ تا ۳۰۰ mL/h ادرار. قلیایی‌سازی ادرار با بیکربنات یا دیورز اجباری (مانیتول، لوپ) شواهد ندارد؛ مانیتول در بیمار هیپوولمیک ممکن است مضر باشد؛ اگر بیکربنات: ایزوتونیک و پرهیز از آلکالوز متابولیک و هیپوکالمی. کاتتر ادراری در بیمار بحرانی یا نارسایی کلیه؛ مانیتور قلبی؛ در بیماران قلبی/کلیوی/سالمند پایش همودینامیک. هیپوکلسمی اولیه معمولاً درمان نمی‌خواهد؛ کلسیم برای کاردیوتوکسیسیته هیپرکالمی یا علائم شدید. هیپرفسفاتمی > 7 mg/dL با باندر خوراکی؛ هیپوفسفاتمی < 1 mg/dL درمان. هیپرکالمی: انسولین و گلوکز ممکن است کمتر مؤثر باشد؛ رزین تبادل یونی (sodium polystyrene sulfonate) مؤثر؛ ممکن است دیالیز. از NSAID پرهیز. درمان علت زمینه‌ای.","pearls":["دیپ‌استیک خون مثبت و RBC منفی = میوگلوبینوری.","NSAID ممنوع (انقباض عروق کلیه)."],"section":"renal-genitourinary","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 51: Rhabdomyolysis, pp. 292–295"},"esrd-cardio-neuro-heme":{"id":"esrd-cardio-neuro-heme","variants":[{"id":"esrd-pulm-edema-hyperk","o":{"L":[{"t":"Troponin (rise of 20% or greater with at least one value above the 99th percentile defines MI)"}],"T":[{"t":"Supplemental oxygen and bilevel positive airway pressure"},{"t":"Nitrates","fl":[{"k":"note","v":"dose not given in the book"}]},{"t":"Furosemide 60 to 100 mg IV (pulmonary vasodilator effect may provide relief even in oliguric patients)","fl":[{"k":"renal","v":"oliguria"}]},{"t":"Angiotensin converting enzyme inhibitor","fl":[{"k":"note","v":"drug and dose not given in the book"}]},{"t":"Reduce preload: induce diarrhea with sorbitol; phlebotomy (minimum 150 mL, collected in a transfusion bag to be transfused back during subsequent dialysis)"}],"Co":[{"t":"Nephrology for emergent hemodialysis (definitive treatment)"}]},"name":"ESRD with pulmonary edema / hyperkalemia needing emergent dialysis","level":"I","imp":"ESRD with pulmonary edema / hyperkalemia","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"مرد ۶۰ ساله دیالیزی با جاماندن جلسه، تنگی نفس، رال و پتاسیم 7.","why":"دیالیز اورژانس برای هیپرکالمی، اسیدوز شدید و ادم ریه مقاوم؛ هیچ مایع نرمال سالینی نده."},{"id":"esrd-uremic-pericarditis-tamponade","o":{"I":[{"t":"Echocardiography (confirms tamponade; enlarged heart on chest x-ray may suggest it)"}],"T":[{"t":"Pericardiocentesis under fluoroscopic or ultrasonographic guidance for a hemodynamically significant pericardial effusion"}],"Co":[{"t":"Nephrology for intensive dialysis (uremic pericarditis); cardiology"}]},"name":"Uremic pericarditis / tamponade","level":"I","imp":"Uremic pericarditis with possible cardiac tamponade","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"مرد ۵۵ ساله ESRD با تنگی نفس، افت فشار و تغییر هوشیاری؛ ساییدگی پریکارد.","why":"تامپوناد جدی‌ترین عارضه؛ اکو و پریکاردیوسنتز؛ پریکاردیت با دیالیز فشرده."},{"id":"esrd-uremic-encephalopathy","o":{"I":[{"t":"Head CT (stroke considered in any ESRD patient with a change in mental status; half of strokes are hemorrhagic, typically subdural hematomas)","fl":[{"k":"note","v":"CT not specifically stated in the chapter"}]}],"L":[{"t":"Glucose and tests to exclude structural, vascular, infectious, toxic and metabolic causes"}],"Co":[{"t":"Nephrology for hemodialysis (progressive neurologic symptoms of uremia are the most common indication for initiating HD)"}]},"name":"Altered mental status in ESRD (uremic encephalopathy vs stroke)","level":"II","imp":"Altered mental status in ESRD (uremic encephalopathy, rule out stroke)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","sc":"مرد ۶۵ ساله دیالیزی با گیجی، تکلم نامفهوم و asterixis.","why":"اورمیک تشخیص رد سایر علل است؛ در تغییر هوشیاری به سکته (ساب‌دورال) فکر کن."},{"id":"esrd-bleeding","o":{"T":[{"t":"Desmopressin 0.3 μg/kg or cryoprecipitate"}],"Co":[{"t":"Nephrology; GI / surgery as appropriate"}]},"name":"ESRD with bleeding (uremic platelet dysfunction)","level":"II","imp":"Bleeding in ESRD (abnormal hemostasis)","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زن ۵۸ ساله دیالیزی با ملنا.","why":"هموستاز غیرطبیعی؛ دسموپرسین یا کرایو."}],"ch":"52","name":"ESRD: cardiovascular, neurologic and hematologic emergencies","name_fa":"اورژانس‌های بیماران ESRD: قلبی-عروقی، عصبی و خونی","cc":["dyspnea","altered-mental-status","chest-pain","bleeding-bruising"],"keywords":"ESRD, dialysis, uremic pericarditis, tamponade, uremic encephalopathy, asterixis, troponin, desmopressin, pulmonary edema, furosemide, نارسایی کلیه مزمن","status":"draft","features":["موارد دیالیز اورژانس: هیپرکالمی، اسیدوز متابولیک شدید و ادم ریه مقاوم به درمان‌های دیگر","ترویونین I و T در ESRD حتی بدون علامت شایع است؛ MI با افزایش ≥ 20٪ ترویونین و حداقل یک مقدار بالای صدک 99","فشار خون بالا در بیشتر بیماران شروع‌کننده دیالیز؛ نارسایی قلبی: فشار، ایسکمی، دریچه‌ای، کاردیومیوپاتی اورمیک، اضافه حجم و فیستول AV (high output)","پریکاردیت اورمیک: معمولاً با بدتر شدن اورمی؛ تغییرات ECG تیپیک همیشه نیست؛ ساییدگی پریکارد بلندتر و اغلب لمس‌شدنی؛ تامپوناد جدی‌ترین عارضه (تغییر هوشیاری، افت فشار، تنگی نفس؛ قلب بزرگ در CXR؛ تأیید با اکو)","آنسفالوپاتی اورمیک: تغییر هوشیاری، نقص شناختی، فراموشی، تکلم نامفهوم و asterixis؛ شایع‌ترین اندیکاسیون شروع HD؛ تشخیص رد سایر علل ساختاری، عروقی، عفونی، توکسیک و متابولیک","نوروپاتی محیطی در 60٪ تا 100٪؛ دیس‌اتونومی؛ سکته مغزی در 6٪ HD (نیمی خونریزی‌دهنده، معمولاً ساب‌دورال) – در هر تغییر هوشیاری به سکته فکر کن","کم‌خونی (کاهش اریتروپویتین، خونریزی، فلبوتومی، عمر کم RBC)؛ هموستاز غیرطبیعی: خونریزی GI، هماتوم ساب‌کپسولار کبد، ساب‌دورال، داخل چشمی؛ نقص ایمنی و مرگ‌ومیر بالای عفونت"],"ddx":[{"n":"Hyperkalemia / severe metabolic acidosis |","cm":1},{"n":"Cardiac tamponade (uremic pericarditis) |","cm":1},{"n":"Stroke (including subdural hematoma) |","cm":1},{"n":"Acute coronary syndrome |"},{"n":"Uremic encephalopathy (diagnosis of exclusion) |"},{"n":"Fluid overload / pulmonary edema |"}],"redflags":["تامپوناد (تغییر هوشیاری، افت فشار، تنگی نفس)، هیپرکالمی، ادم ریه مقاوم، تغییر هوشیاری (سکته)، خونریزی"],"guide":"# CHF و اضافه حجم\nاکسیژن، BiPAP، نیترات، ACE inhibitor و احتمالاً furosemide 60 تا 100 mg IV (اثر وازودیلاتور ریوی حتی در اولیگوری)؛ کاهش پیش‌بار با ایجاد اسهال با sorbitol و فلبوتومی (حداقل 150 mL، در کیسه انتقال خون برای بازگرداندن در دیالیز)؛ HD درمان قطعی.\n# فشار خون\nکنترل حجم خون سپس مسدودکننده آدرنرژیک، ACE inhibitor یا وازودیلاتور.\n# پریکاردیت اورمیک\nدیالیز فشرده؛ تامپوناد: پریکاردیوسنتز با هدایت فلوروسکوپی یا سونوگرافی.\n# خونریزی\ndesmopressin 0.3 μg/kg یا cryoprecipitate.","pearls":["ترویونین در ESRD مزمناً بالاست؛ به روند (≥ 20٪) توجه کن.","آنسفالوپاتی اورمیک تشخیص رد سایر علل است."],"section":"renal-genitourinary","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 52: Emergencies in Renal Failure and Dialysis Patients, pp. 296–298"},"dialysis-complications":{"id":"dialysis-complications","variants":[{"id":"dialysis-intradialytic-hypotension","o":{"T":[{"t":"Trendelenburg positioning, oral salt solution or infusion of normal saline","fl":[{"k":"ci","v":"heart failure / pulmonary edema"}]},{"t":"If these fail, excessive ultrafiltration is unlikely; further evaluation required (myocardial ischemia, hypoxia, arrhythmia, pericardial tamponade, sepsis, antihypertensives, GI bleeding, blood tubing or filter leaks)"}],"Co":[{"t":"Nephrology"}]},"name":"Intradialytic hypotension","level":"II","imp":"Intradialytic hypotension","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","sc":"مرد ۶۰ ساله هنگام همودیالیز با افت فشار 80/50 و سرگیجه.","why":"معمولاً اولترافیلتراسیون زیاد؛ Trendelenburg و سالین؛ در شکست علل دیگر (ایسکمی، تامپوناد، سپسیس، خونریزی)."},{"id":"dialysis-disequilibrium","o":{"T":[{"t":"Terminate dialysis"},{"t":"Mannitol IV to increase serum osmolality","fl":[{"k":"note","v":"dose not given in the book"}]}],"Co":[{"t":"Nephrology; admit"}]},"name":"Dialysis disequilibrium syndrome","level":"I","imp":"Dialysis disequilibrium (cerebral edema)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مرد ۴۵ ساله نخستین جلسه HD با تهوع، استفراغ، فشار بالا و تشنج.","why":"ادم مغزی؛ قطع دیالیز و مانیتول."},{"id":"dialysis-access-problem","o":{"L":[{"t":"Peripheral and catheter blood cultures simultaneously (fourfold higher colony count in the catheter culture suggests it is the source)"}],"A":[{"t":"Vancomycin 15 mg/kg IV and an aminoglycoside such as Gentamycin 100 mg IV","if":"vascular access infection"}],"T":[{"t":"Direct pressure at the puncture site for 5 to 10 minutes; if this fails, absorbable gelatin sponge soaked in reconstituted thrombin or prothrombotic gauze followed by 10 minutes of direct pressure","if":"bleeding"},{"t":"tourniquet proximal to the access","if":"life-threatening hemorrhage"},{"t":"Protamine 0.01 mg per unit heparin dispensed during dialysis, or 10 to 20 mg protamine if heparin dose unknown","if":"excessive anticoagulation"},{"t":"Desmopressin 0.3 μg/kg IV as an adjunct to direct pressure","if":"newly inserted access continues to bleed"}],"Co":[{"t":"Thrombosis or stenosis: treatment within 24 hours (angiographic clot removal, angioplasty, or thrombolytic injected directly into the access); vascular surgery for life-threatening hemorrhage; hospitalization for access infection"}]},"name":"Vascular access thrombosis, infection or bleeding","level":"II","imp":"Vascular access complication (thrombosis / infection / hemorrhage)","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مرد ۶۸ ساله با از بین رفتن thrill فیستول یا تب و افت فشار با کاتتر دیالیز.","why":"ترومبوز: ظرف 24 ساعت؛ عفونت: کشت همزمان و آنتی‌بیوتیک؛ خونریزی: فشار و برگرداندن هپارین."},{"id":"dialysis-pd-peritonitis","o":{"L":[{"t":"Peritoneal fluid: cell count, Gram stain, culture and sensitivity (> 100 leukocytes/mm3 with > 50% neutrophils supports peritonitis)"}],"A":[{"t":"Added to the dialysate: gram-positive coverage (cephalothin or Vancomycin 500 mg/L dialysate) and gram-negative coverage (Gentamycin 100 mg/L dialysate)"},{"t":"first-generation cephalosporin or Ciprofloxacin (outpatient)","if":"infection around the PD catheter","fl":[{"k":"note","v":"dose not given in the book"}]}],"T":[{"t":"A few rapid exchanges of dialysate to decrease inflammatory cells in the peritoneum"},{"t":"Heparin 500 to 1000 U/L dialysate to decrease fibrin clot formation"}],"Co":[{"t":"Inpatient versus outpatient treatment based on clinical presentation; nephrology"}]},"name":"Peritoneal dialysis peritonitis / catheter infection","level":"II","imp":"Peritoneal dialysis peritonitis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"زن ۵۰ ساله با PD، تب، درد شکم و مایع خروجی کدر.","why":"پریتونیت شایع‌ترین عارضه PD؛ آنتی‌بیوتیک داخل دیالیزات."}],"ch":"52","name":"Complications of hemodialysis, vascular access and peritoneal dialysis","name_fa":"عوارض همودیالیز، دسترسی عروقی و دیالیز صفاقی","cc":["hypotension-shock","fever","bleeding-bruising","abdominal-pain"],"keywords":"intradialytic hypotension, dialysis disequilibrium, AV fistula thrombosis, vascular access infection, protamine, desmopressin, peritoneal dialysis peritonitis, cloudy effluent, vancomycin, gentamicin, عوارض دیالیز","status":"draft","features":["افت فشار شایع‌ترین عارضه HD؛ علت: اولترافیلتراسیون بیش از حد (کمتر از وزن خشک)؛ علل دیگر: ایسکمی/آریتمی/تامپوناد، سپسیس یا داروهای ضدفشار، از دست دادن حجم (استفراغ، اسهال، خونریزی GI، نشت فیلتر)","دیس‌اکوئیلیبریوم: ادم مغزی پس از پاکسازی املاح؛ تهوع، استفراغ، فشار بالا → تشنج، کما، مرگ","دسترسی عروقی: بیشترین روزهای بستری؛ ترومبوز/تنگی با از بین رفتن bruit و thrill (درمان ظرف 24 ساعت)","عفونت دسترسی: تب، افت فشار، لکوسیتوز؛ علائم موضعی اغلب غایب؛ S. aureus شایع‌ترین؛ کشت خون محیطی و کاتتر همزمان (کلنی 4 برابر در کاتتر = منبع)","خونریزی تهدیدکننده از پارگی آنوریسم/آناستوموز یا ضدانعقاد بیش از حد","پریتونیت PD شایع‌ترین عارضه PD: تب، درد شکم، تندرنس برگشتی؛ مایع خروجی کدر؛ > 100 WBC/mm3 با > 50٪ نوتروفیل؛ گرم مثبت فقط در 10٪ تا 40٪؛ S. epidermidis، S. aureus، استرپتوکوک و گرم‌منفی","عفونت اطراف کاتتر PD: درد، اریتم، تورم، ترشح؛ S. aureus و Pseudomonas"],"ddx":[{"n":"Sepsis from vascular access infection |","cm":1},{"n":"Cardiac tamponade / myocardial ischemia (intradialytic hypotension) |","cm":1},{"n":"Hemorrhage from vascular access |","cm":1},{"n":"Dialysis disequilibrium / intracranial hemorrhage |"},{"n":"Peritonitis / catheter exit-site infection |"}],"redflags":["شوک یا سپسیس، خونریزی تهدیدکننده حیات از دسترسی، تشنج یا کما حین دیالیز"],"guide":"# افت فشار حین HD\nوضعیت Trendelenburg، محلول نمکی خوراکی یا نرمال سالین؛ اگر جواب نداد اولترافیلتراسیون زیاد بعید است و باید بیشتر بررسی شود.\n# دیس‌اکوئیلیبریوم\nقطع دیالیز و مانیتول وریدی.\n# ترومبوز دسترسی\nظرف 24 ساعت: برداشتن لخته آنژیوگرافیک، آنژیوپلاستی یا تزریق مستقیم ترومبولیتیک.\n# عفونت دسترسی\nبستری؛ vancomycin 15 mg/kg IV و آمینوگلیکوزید مثل gentamycin 100 mg IV.\n# خونریزی دسترسی\nفشار ۵ تا ۱۰ دقیقه؛ در شکست: اسفنج ژلاتینی جذب‌شدنی آغشته به ترومبین یا گاز پروترومبوتیک و ۱۰ دقیقه فشار؛ تهدیدکننده حیات: تورنیکه پروگزیمال و مشاوره جراحی عروق؛ هپارین: protamine 0.01 mg به‌ازای هر واحد هپارین یا 10 تا 20 mg اگر مقدار نامعلوم؛ دسترسی تازه که خونریزی ادامه دارد: desmopressin 0.3 μg/kg IV.\n# پریتونیت PD\nمایع صفاقی برای شمارش سلول، گرم، کشت و حساسیت؛ چند تعویض سریع دیالیزات؛ هپارین 500 تا 1000 U/L دیالیزات؛ آنتی‌بیوتیک در دیالیزات: cephalothin یا vancomycin 500 mg/L و gentamycin 100 mg/L؛ بستری یا سرپایی بر اساس بالین. عفونت اطراف کاتتر: سفالوسپورین نسل اول یا ciprofloxacin سرپایی.","pearls":["در دسترسی عروقی عفونی، علائم کلاسیک موضعی اغلب نیست؛ کشت خون همزمان بگیر."],"section":"renal-genitourinary","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 52: Emergencies in Renal Failure and Dialysis Patients, pp. 296–298"},"urinary-tract-infection":{"id":"urinary-tract-infection","variants":[{"id":"uti-uncomplicated-cystitis","o":{"L":[{"t":"Urine dipstick (nitrite, leukocyte esterase) or urinalysis; urine culture not needed in uncomplicated cystitis"}],"A":[{"t":"Nitrofurantoin 100 mg extended release twice a day PO for 5 days (first-line); alternatives: TMP-SMX DS 160/800 mg twice a day for 3 days, or Fosfomycin 3 g single dose","fl":[{"k":"ci","v":"avoid fluoroquinolones in uncomplicated UTI"}]}],"T":[{"t":"Phenazopyridine 200 mg three times a day for 2 days (bladder analgesic)"},{"t":"Encourage adequate hydration; complete the entire antibiotic course"}],"Co":[{"t":"Outpatient follow-up with a primary care doctor; return for uncontrolled pain, fever, vomiting"}]},"name":"Uncomplicated cystitis (young healthy non-pregnant woman)","level":"III","imp":"Uncomplicated cystitis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۲۵ ساله با سوزش ادرار و تکرر ادرار؛ بدون تب.","why":"UTI بدون عارضه با nitrofurantoin؛ فلوروکینولون پرهیز برای کاهش مقاومت."},{"id":"uti-complicated-pyelonephritis","o":{"I":[{"t":"CT or ultrasound only if severe or nonresponsive pyelonephritis, or significant concern for a renal stone"}],"L":[{"t":"Urinalysis and urine culture (complicated UTI)"}],"A":[{"t":"Ciprofloxacin 500 mg twice a day for 7 days (first-line); alternatives: Levofloxacin 750 mg daily for 5 days, or Cefpodoxime 400 mg twice a day for 7 to 14 days; TMP-SMX DS 160/800 mg twice a day for 7 to 14 days or Amoxicillin-clavulanate 875/125 mg twice a day for 14 days if local resistance is less than 20%"},{"t":"Ceftriaxone 1 g IV daily, or Ciprofloxacin 400 mg IV every 12 hours, or Piperacillin-tazobactam 3.375 g IV every 6 hours","if":"inpatient"}],"T":[{"t":"Phenazopyridine 200 mg three times a day for 2 days"}],"Co":[{"t":"Admit if intractable vomiting or inadequate outpatient follow-up"}]},"name":"Pyelonephritis / complicated UTI (man, structural abnormality, comorbidity)","level":"II","imp":"Pyelonephritis / complicated UTI","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"مردی ۵۰ ساله با تب، لرز، درد فلانک و تکرر ادرار.","why":"عارضه‌دار: کشت ادرار و کموکینولون خط اول؛ بستری اگر استفراغ مقاوم."},{"id":"uti-pregnancy","o":{"L":[{"t":"Urinalysis and urine culture (pregnant women)"}],"A":[{"t":"Asymptomatic bacteriuria: Nitrofurantoin for 3 days; UTI: Nitrofurantoin for 7 days","fl":[{"k":"ci","v":"fluoroquinolones and tetracyclines are teratogenic; TMP-SMX with caution in the first and third trimesters"}]}],"Co":[{"t":"Consider admission for pregnant women (20% will develop sepsis)"}]},"name":"UTI or asymptomatic bacteriuria in pregnancy","level":"II","imp":"Urinary tract infection in pregnancy","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"زنی ۲۸ ساله با حاملگی ۱۶ هفته، سوزش ادرار و کشت مثبت.","why":"حاملگی: 20٪ سپسیس؛ nitrofurantoin؛ پرهیز از فلوروکینولون و تتراسایکلین."}],"ch":"53","name":"Urinary tract infection (cystitis, pyelonephritis, pregnancy, asymptomatic bacteriuria)","name_fa":"عفونت ادراری (سیستیت، پیلونفریت، حاملگی، باکتریوری بدون علامت)","cc":["urinary-symptoms","flank-pain","fever"],"keywords":"UTI, cystitis, pyelonephritis, nitrofurantoin, fosfomycin, ciprofloxacin, ceftriaxone, phenazopyridine, asymptomatic bacteriuria, dysuria, عفونت ادراری","status":"draft","features":["شایع‌ترین عفونت باکتریال سرپایی؛ بیش از 50٪ زنان یک بار و حدود 12٪ سالانه","پایین: اورتریت (ترشح؛ معمولاً آمیزشی) و سیستیت؛ بالا: پیلونفریت؛ تمایز بالینی","بدون عارضه: زن جوان سالم غیرحامله با مجاری طبیعی؛ عارضه‌دار: همه مردان، حاملگی، ناهنجاری ساختاری/عملکردی یا بیماری زمینه‌ای","ABU: باکتری قابل‌توجه (≥ 100000 CFU/mL یک ارگانیسم) بدون علامت؛ غربالگری/درمان عموماً توصیه نمی‌شود مگر حاملگی یا قبل از TURP","بیش از 80٪ E. coli؛ Klebsiella، Proteus، Enterobacter، Pseudomonas، Chlamydia، S. saprophyticus","سیستیت: تکرر، فوریت، تردید و درد سوپراپوبیک؛ پیلونفریت: درد فلانک یا CVA همراه تب، لرز یا تهوع/استفراغ","ترشح واژینال/مجرا: اورتریت، واژینیت، سرویسیت یا PID محتمل‌تر؛ دیابتی و سالمند آتیپیک (ضعف، بی‌حالی، درد شکم، تغییر هوشیاری)","دیپ‌استیک: نیتریت (ویژگی > 90٪، حساسیت 50٪)، لکوسیت استراز (حساسیت 77٪)؛ هرکدام مثبت حساسیت 75٪، ویژگی 82٪؛ هر دو مثبت ویژگی 98 تا 100٪؛ منفی رد نمی‌کند"],"ddx":[{"n":"Pyelonephritis with sepsis / obstructing stone |","cm":1},{"n":"Pelvic inflammatory disease |","cm":1},{"n":"Vaginitis / cervicitis / urethritis |"},{"n":"Prostatitis / epididymitis |"},{"n":"Intra-abdominal pathology / bladder tumor |"},{"n":"Chemical irritation / trauma |"}],"redflags":["سپسیس، استفراغ مقاوم، انسداد با سنگ، حاملگی (20٪ سپسیس)، مرد یا بیمار با پیگیری ناکافی"],"guide":"تشخیص با شرح حال و معاینه، تأیید با دیپ‌استیک یا UA و کشت. نمونه میان‌جریان تمیز به دقت کاتتر است؛ کاتتر فقط اگر قادر به ادرار نیست، بسیار بدحال/بی‌حرکت یا چاق شدید (1٪ تا 2٪ UTI بعد از یک کاتتر). کشت فقط: عارضه‌دار (مرد، حاملگی)، عود یا عفونت مجدد، کودکان، سپتیک. تصویربرداری (CT یا سونو) فقط در پیلونفریت شدید/غیرپاسخگو یا شک به سنگ. اگر تست‌ها مبهم است درمان تجربی.\n\n# آنتی‌بیوتیک\nبدون عارضه: nitrofurantoin 100 mg ER دو بار روزانه ۵ روز (خط اول)؛ TMP-SMX DS 160/800 mg دو بار روزانه ۳ روز؛ fosfomycin 3 g دوز واحد؛ فلوروکینولون پرهیز. عارضه‌دار/پیلونفریت: ciprofloxacin 500 mg دو بار روزانه ۷ روز (خط اول)؛ levofloxacin 750 mg روزانه ۵ روز؛ cefpodoxime 400 mg دو بار روزانه ۷ تا ۱۴ روز؛ اگر مقاومت محلی < 20٪: TMP-SMX DS ۷ تا ۱۴ روز یا amoxicillin-clavulanate 875/125 mg دو بار روزانه ۱۴ روز.\nحاملگی: ABU ۳ روز و UTI ۷ روز nitrofurantoin؛ فلوروکینولون و تتراسایکلین تراتوژن؛ TMP-SMX با احتیاط در سه‌ماهه اول و سوم.\nعلاوه بر آن phenazopyridine 200 mg سه بار روزانه ۲ روز. بستری: پیلونفریت با استفراغ مقاوم؛ حاملگی؛ پیگیری نامناسب. تزریقی: ceftriaxone 1 g IV روزانه، ciprofloxacin 400 mg IV هر ۱۲ ساعت یا piperacillin-tazobactam 3.375 g IV هر ۶ ساعت.","pearls":["هیچ تست واحدی UTI را در زنان علامت‌دار رد نمی‌کند؛ در نتایج مبهم درمان تجربی."],"section":"renal-genitourinary","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 53: Urinary Tract Infections and Hematuria, pp. 299–302"},"hematuria":{"id":"hematuria","variants":[{"id":"hematuria-stable","o":{"L":[{"t":"Urinalysis with microscopy (positive dipstick followed by microscopy)"}],"Co":[{"t":"Prompt follow-up with primary care or urology"}]},"name":"Hematuria, stable","level":"III","imp":"Hematuria","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۶۵ ساله با هماچوری بدون درد؛ علائم حیاتی پایدار.","why":"درمان علت؛ پیگیری پزشک عمومی/اورولوژی."},{"id":"hematuria-unstable","o":{"I":[{"t":"Imaging only for trauma, symptoms of nephrolithiasis, or high concern for abdominal aortic aneurysm"}],"L":[{"t":"Urinalysis with microscopy"}],"Co":[{"t":"Admit; urology / nephrology as appropriate"}]},"name":"Hematuria with instability or complications","level":"II","imp":"Hematuria with hemodynamic instability / obstruction / renal insufficiency","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مردی ۷۰ ساله با هماچوری و لخته، افت فشار و کراتینین بالا.","why":"ناپایداری، انسداد یا نارسایی کلیه بستری لازم دارد؛ تصویربرداری فقط در تروما، سنگ یا شک AAA."}],"ch":"53","name":"Hematuria","name_fa":"هماچوری","cc":["urinary-symptoms","flank-pain"],"keywords":"hematuria, gross hematuria, microscopic hematuria, painless hematuria, bladder cancer, glomerulonephritis, خون در ادرار","status":"draft","features":["هماچوری ماکروسکوپیک: منبع تحتانی؛ رنگدانه‌هایی مثل میوگلوبین می‌توانند تقلید کنند؛ میکروسکوپیک (> 3 RBC/HPF): منبع کلیوی (در UTI هم دیده می‌شود)","دیپ‌استیک با حدود 5 تا 20 RBC/mL مثبت؛ مثبت را با میکروسکوپی دنبال کن؛ کاتتر در 15٪ هماچوری ایجاد می‌کند؛ مثبت کاذب: میوگلوبین، همولیز، پورفیرین؛ منفی کاذب: وزن مخصوص بالا","UTI شایع‌ترین علت همراه فوریت/سوزش/شب‌ادراری؛ هماچوری بدون درد: نئوپلاسم، هیپرپلازی، عروقی","< 40 سال: عفونت و التهاب (UTI، پروستاتیت، اورتریت، STD، اپیدیدیمواورکیت، سنگ، سل)؛ سن بالا: سرطان کلیه/مثانه/پروستات، BPH","سایر: ورزش شدید، پس از استرپتوکوک، تروما، هیپرتانسیون بدخیم، AAA فرساینده، کواگولوپاتی، جسم خارجی، HSP، سندرم ریوی-کلیوی، سیکل‌سل، ترومبوز ورید کلیوی","هماچوری در بیمار با ضدانعقاد خوراکی را فقط به دارو نسبت نده (تا 80٪ بیماری زمینه‌ای)"],"ddx":[{"n":"Eroding abdominal aortic aneurysm |","cm":1},{"n":"Renal or bladder cancer |","cm":1},{"n":"Urinary tract infection / prostatitis |"},{"n":"Nephrolithiasis |"},{"n":"Glomerulonephritis / Henoch-Schonlein purpura |"},{"n":"Trauma / coagulopathy / sickle cell disease |"}],"redflags":["ناپایداری همودینامیک، کم‌خونی قابل‌توجه، نارسایی کلیه، انسداد خروجی مثانه، پره‌اکلامپسی، گلومرولونفریت تازه‌تشخیص"],"guide":"درمان بر اساس علت؛ در ED کاهش عوارض و ارجاع یا بستری. همه بیماران باید به‌سرعت توسط پزشک عمومی یا اورولوژی پیگیری شوند. تصویربرداری در ED فقط: تروما، علائم سنگ یا شک بالا به AAA. بستری: عفونت همراه سنگ انسدادی، درد/استفراغ مقاوم، ناپایداری همودینامیک، گلومرولونفریت جدید، کم‌خونی قابل‌توجه، نارسایی کلیه، انسداد خروجی مثانه، پره‌اکلامپسی یا هر علت تهدیدکننده.","section":"renal-genitourinary","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 53: Urinary Tract Infections and Hematuria, pp. 299–302"},"acute-urinary-retention":{"id":"acute-urinary-retention","variants":[{"id":"retention-uncomplicated","o":{"I":[{"t":"Bedside ultrasound after a voiding attempt (bladder volume; residual > 50 to 150 cc consistent with retention, typically > 300 cc)"}],"L":[{"t":"Urinalysis and urine culture; electrolytes, BUN and creatinine for postobstructive renal failure"}],"T":[{"t":"Urethral catheter with copious intraurethral lubrication including 2% lidocaine jelly; 16-French Coude catheter if straight catheters fail; pass to its fullest extent for free urine flow before inflating the balloon; leave indwelling with leg drainage bag"},{"t":"Monitor urine output quantitatively; if chronic retention, closely monitor for 4 to 6 hours after catheterization (output > 200 mL/h for more than 4 to 6 hours: admit and replace fluid)"},{"t":"Oxybutynin for bladder spasms","fl":[{"k":"ci","v":"anticholinergic, can itself cause functional obstruction"}]},{"t":"Alpha-blocker if BPH suspected","fl":[{"k":"note","v":"drug and dose not given in the book"}]},{"t":"Discontinue offending medications"}],"A":[{"t":"Antibiotics","if":"cystitis or other infection","fl":[{"k":"note","v":"not indicated otherwise; drug and dose not given in the book"}]}],"Co":[{"t":"Urologic follow-up in 3 to 7 days for complete genitourinary evaluation and catheter removal"}]},"name":"Acute urinary retention (BPH, medication), uncomplicated","level":"II","imp":"Acute urinary retention","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"مردی ۷۲ ساله با ناتوانی در ادرار و درد زیر شکم از ۱۲ ساعت پیش.","why":"کاتتر ادراری ساده درد را برطرف می‌کند؛ پایش دیورز پس از انسداد و پیگیری اورولوژی."},{"id":"retention-hematuria-failed","o":{"L":[{"t":"Urinalysis and urine culture; electrolytes, BUN and creatinine"}],"T":[{"t":"3-port Foley catheter; irrigate the bladder until returning fluid is free of blood (catheter often becomes blocked with clot)"},{"t":"Do not place a catheter if urethral trauma is suspected (trauma or recent instrumentation); suprapubic urinary catheter may be placed by physicians familiar with the procedure"}],"Co":[{"t":"Urologist for catheter placement without delay (failure to pass Foley, recent urologic procedure or instrumentation); urgent urologic consultation for stricture, prostatitis or urethral trauma"},{"t":"Admit for continued irrigation"}]},"name":"Retention with clot hematuria, urethral trauma, stricture or failed catheterization","level":"II","imp":"Acute urinary retention with hematuria / failed catheterization","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مردی ۶۸ ساله با لخته و هماچوری، احتباس ادرار و شکست کاتتریزاسیون.","why":"Foley سه‌راهه و شست‌وی؛ شکست کاتتر یا پروسیجر اخیر: اورولوژی بدون تأخیر."}],"ch":"54","name":"Acute urinary retention","name_fa":"احتباس حاد ادرار","cc":["urinary-symptoms","abdominal-pain"],"keywords":"urinary retention, BPH, Foley, Coude, suprapubic catheter, three-way catheter, alpha blocker, postobstructive diuresis, oxybutynin, احتباس ادرار","status":"draft","features":["شایع‌ترین علت: انسداد خروجی توسط BPH در مردان؛ دارو، اختلال حاد عصبی، خونریزی یا سنگ و سایر انسدادهای آناتومیک در هر دو جنس","حاد: شروع سریع درد زیر شکم گاهی تیر به کمر؛ مشکل در ادرار (ممکن است بیمار ذکر نکند)؛ 20٪ عود در 6 ماه بعد؛ مزمن: ناراحتی زیر شکم، تخلیه ناقص، تکرر، بی‌اختیاری سرریز","شرح حال: اپیزودهای قبلی، تغییر دارو، داروهای OTC، تروما، نقص عصبی، عفونت، پروسیجر اورولوژیک یا کاتتر اخیر؛ مدت علائم (دیورز پس از انسداد و اختلال کلیه)","معاینه: توده سوپراپوبیک؛ تنگی میتوس؛ پروستات (اندازه، قوام، تندرنس)؛ پرولاپس مثانه یا تنگی میتوس در زنان؛ معاینه لگن؛ معاینه عصبی کامل با حس پرینه و تون اسفنکتر","سونوگرافی بالین بعد از تلاش برای ادرار: حجم باقیمانده > 50 تا 150 cc مطابق احتباس؛ معمولاً > 300 cc در احتباس؛ افتراق از اسپاسم مثانه"],"ddx":[{"n":"Cauda equina / spinal cord compression |","cm":1},{"n":"Urethral trauma |","cm":1},{"n":"Benign prostatic hyperplasia |"},{"n":"Urinary tract infection / prostatitis |"},{"n":"Medication side effect (anticholinergic) / stricture / stone / clot |"}],"redflags":["تب (عفونت)، شک به تروما/اورتر، نقص عصبی (بی‌حسی زین اسبی، تون اسفنکتر ضعیف)، شکست کاتتریزاسیون"],"guide":"کاتتر ادراری درد و احتباس را برطرف می‌کند: روان‌کننده فراوان داخل مجرا با بی‌حسی موضعی (ژل lidocaine 2٪)؛ اگر کاتتر مستقیم شکست: Coudé 16-French؛ تا آخر پیش ببر تا ادرار آزاد بیاید قبل از باد کردن بالون؛ در شک تروما به مجرا یا دستکاری اخیر کاتتر نگذار. معمولاً کاتتر دائم با کیسه پا؛ در احتباس پس از بیهوشی: کاتتر خارج و آزمایش ادرار خودبه‌خود.\nهماچوری انسدادی: Foley سه‌راهه و شست‌وی مثانه تا مایع بدون خون؛ احتمالاً بستری (انسداد کاتتر با لخته).\nشکست کاتتریزاسیون یا پروسیجر اخیر: اورولوژی؛ فوری در تنگی، پروستاتیت یا تروما؛ کاتتر سوپراپوبیک.\nارسال UA و کشت؛ الکترولیت، BUN و کراتینین؛ پایش کمی ادرار. oxybutynin برای اسپاسم مثانه (می‌تواند خود انسداد عملکردی دهد)؛ BPH: مسدودکننده α. آنتی‌بیوتیک فقط در شواهد سیستیت/عفونت. انسداد مزمن: دیورز پس از انسداد حتی با BUN/Cr نرمال؛ پایش ۴ تا ۶ ساعت؛ > 200 mL/h برای بیش از ۴ تا ۶ ساعت: بستری و مایع. قطع داروی مسبب. پیگیری اورولوژی ۳ تا ۷ روز.","pearls":["قبل از بالون زدن کاتتر مطمئن شو ادرار آزاد جاری است.","در شک به تروما مجرا کاتتر نگذار."],"section":"renal-genitourinary","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 54: Acute Urinary Retention, pp. 303–305"},"testicular-torsion":{"id":"testicular-torsion","variants":[{"id":"torsion-suspected","o":{"I":[{"t":"Color-flow duplex ultrasound (sensitivity 69% to 90%); do not delay urologic consultation when the diagnosis is obvious"}],"L":[{"t":"Urinalysis (pyuria does not rule out torsion)"}],"T":[{"t":"Manual detorsion by the emergency physician in a medial to lateral direction (like opening a book); endpoint is pain relief"},{"t":"Analgesia","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"Co":[{"t":"Immediate urologic consultation for exploration (salvage rates excellent within 6 hours of symptom onset); consult early even if confirmatory testing is planned"}]},"name":"Suspected testicular torsion","level":"I","imp":"Testicular torsion","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"پسری ۱۴ ساله با درد ناگهانی شدید بیضه چپ پس از ورزش و تهوع؛ بیضه بالا کشیده و تندر.","why":"زمان از دست دادن بیضه را تعیین می‌کند؛ بدون تأخیر اورولوژی و اتاق عمل؛ NPO برای عمل."},{"id":"torsion-appendage","o":{"I":[{"t":"Color Doppler to demonstrate normal intratesticular blood flow"}],"T":[{"t":"Analgesia","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"Co":[{"t":"Urologic follow-up (most appendages calcify or degenerate over 10 to 14 days)"}]},"name":"Torsion of appendix testis / epididymis","level":"III","imp":"Torsion of testicular appendage","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"پسری ۱۰ ساله با درد نزدیک سر بیضه و ندول تندر کوچک (blue dot)؛ دوپلر جریان طبیعی.","why":"بی‌خطر و خودمحدود است؛ جریان طبیعی بیضه یعنی جراحی لازم نیست."}],"ch":"55","name":"Testicular torsion and torsion of appendages","name_fa":"پیچ‌خوردگی بیضه و زائده‌های بیضه","cc":["genital-complaint","abdominal-pain"],"keywords":"testicular torsion, appendix testis, blue dot sign, cremasteric reflex, manual detorsion, color Doppler, scrotal pain, پیچ‌خوردگی بیضه","status":"draft","features":["ثابت‌شدن غیرطبیعی بیضه در تونیکا واژینالیس؛ توزیع دومودال سنی: دوره پریناتال و بلوغ؛ هر سنی ممکن است؛ معمولاً بدون رویداد قبلی","هر مرد با درد بیضه: ابتدا پیچ‌خوردگی (خطر انفارکتوس و ناباروری)","شروع ناگهانی، شدید در ربع تحتانی شکم، کانال اینگوینال یا بیضه؛ ثابت یا متناوب؛ غیر وضعیتی؛ اغلب بعد از فعالیت یا حین خواب","اوایل: بیضه سفت، دردناک، بالا کشیده و با وضعیت عرضی؛ نبود رفلکس کرماستریک یکطرفه حساس ولی غیراختصاصی","دوپلکس رنگی شایع‌ترین تست تأییدی (حساسیت 69٪ تا 90٪)؛ پیوری رد نمی‌کند","پیچ‌خوردگی زائده شایع‌تر ولی بی‌خطر: درد حداکثر نزدیک سر اپیدیدیم/بیضه، ندول تندر منفرد یا «blue dot» پاتونومونیک در پوست نازک پیش‌بلوغ؛ در جریان خون طبیعی دوپلر نیاز به جراحی نیست (کلسیفیه/دژنره طی 10 تا 14 روز)"],"ddx":[{"n":"Testicular torsion |","cm":1},{"n":"Epididymitis / epididymo-orchitis |"},{"n":"Torsion of appendix testis |"},{"n":"Incarcerated inguinal hernia |"},{"n":"Hydrocele / scrotal hematoma |"},{"n":"Testicular tumor |"}],"redflags":["شروع ناگهانی درد شدید بیضه، بیضه بالا کشیده و عرضی، نبود کرماستریک؛ نجات عالی تا ۶ ساعت و سپس سریع افت می‌کند"],"guide":"وقتی تشخیص واضح است بلافاصله مشاوره اورولوژی برای اکسپلور (تصویربرداری زمان‌بر است). نجات بیضه با detorsion جراحی ظرف ۶ ساعت از شروع علائم عالی است. پزشک اورژانس می‌تواند detorsion دستی را امتحان کند: بیشتر بیضه‌ها از خارج به داخل می‌پیچند، پس detorsion از داخل به خارج مثل باز کردن کتاب؛ نقطه پایان موفقیت: رفع درد؛ ارجاع اورولوژی همچنان لازم است. حتی اگر آزمون تأییدی برنامه‌ریزی شده، اورولوژی را زود صدا کن؛ اگر شک بالا و تست‌ها رد نکند باز هم مشاوره لازم است.","pearls":["پیوری و دوپلر نرمال گاهی گمراه‌کننده است؛ شک بالینی بالا یعنی اورولوژی.","«کتاب باز کردن»: detorsion از داخل به خارج."],"section":"renal-genitourinary","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 55: Male Genital Problems, pp. 306–311"},"epididymitis-orchitis":{"id":"epididymitis-orchitis","variants":[{"id":"epididymitis-outpatient","o":{"I":[{"t":"Color Doppler ultrasound if torsion cannot be excluded","fl":[{"k":"note","v":"not specifically stated for epididymitis in the chapter"}]}],"L":[{"t":"Urinalysis; culture or DNA probe for gonococcus and Chlamydia in males < 35 years even in the absence of urethral discharge"}],"A":[{"t":"Age < 35: Ceftriaxone 250 mg IM single dose plus Doxycycline 100 mg PO twice daily for 10 days"},{"t":"Age > 35: Levofloxacin 500 mg PO daily for 10 days, or Ofloxacin 300 mg PO twice daily for 10 days"}],"T":[{"t":"Scrotal elevation, ice application, nonsteroidal anti-inflammatory drugs, opioids for analgesia, and stool softeners","fl":[{"k":"note","v":"drugs and doses not given in the book"}]}],"Co":[{"t":"Urologic follow-up within 1 week"}]},"name":"Epididymitis, non-toxic","level":"III","imp":"Epididymitis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۲۸ ساله با درد تدریجی بیضه راست و دیزوری؛ غیرسمی.","why":"درمان بر اساس سن: آمیزشی زیر 35 سال و گرم‌منفی در مسن‌تر؛ سرپایی."},{"id":"epididymitis-toxic","o":{"L":[{"t":"Urinalysis and culture"}],"A":[{"t":"Ceftriaxone 1 to 2 g every 12 hours IV, or Trimethoprim/sulfamethoxazole 5 mg/kg IV of trimethoprim component every 6 hours"}],"T":[{"t":"Scrotal elevation, ice, analgesia","fl":[{"k":"note","v":"drugs and doses not given in the book"}]}],"Co":[{"t":"Admission; urology"}]},"name":"Epididymitis, toxic-appearing","level":"II","imp":"Epididymitis with systemic toxicity","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"مردی ۶۵ ساله با تب، لرز و اسکروتوم متورم و دردناک.","why":"بیمار سمی نیاز به بستری و آنتی‌بیوتیک وریدی دارد."}],"ch":"55","name":"Epididymitis and orchitis","name_fa":"اپیدیدیمیت و ارکیت","cc":["genital-complaint"],"keywords":"epididymitis, orchitis, epididymo-orchitis, Prehn sign, gonorrhea, chlamydia, ceftriaxone, doxycycline, levofloxacin, اپیدیدیمیت","status":"draft","features":["شروع تدریجی درد به علت التهاب؛ عفونت باکتریال شایع‌ترین؛ < 35 سال: عمدتاً بیماری‌های آمیزشی (کشت یا DNA probe برای گنوکوک و کلامیدیا حتی بدون ترشح)؛ مسن‌تر: E. coli و Klebsiella","درد تحتانی شکم، کانال اینگوینال، اسکروتوم یا بیضه؛ Prehn مثبت: تسکین موقت با بالا بردن اسکروتوم در حالت خوابیده","ابتدا تندرنس موضعی اپیدیدیم؛ با پیشرفت توده بزرگ واحد بیضه (epididymo-orchitis) که از torsion و کارسینوم سخت افتراق می‌شود","توده بدون علامت، سفتی یا ایندوراسیون: بدخیمی (10٪ تومورها با درد از خونریزی)؛ ارکیت منفرد نادر؛ معمولاً همراه عفونت سیستمیک مثل اوریون"],"ddx":[{"n":"Testicular torsion |","cm":1},{"n":"Testicular tumor |"},{"n":"Inguinal hernia |"},{"n":"Hydrocele / scrotal hematoma |"},{"n":"Prostatitis / urethritis |"}],"redflags":["بیمار سمی، توده بدون درد (تومور)، شک به torsion"],"guide":"بیمار سمی: بستری برای آنتی‌بیوتیک وریدی. غیرسمی: سرپایی با پیگیری اورولوژی ظرف 1 هفته. سن < 35: ceftriaxone 250 mg IM دوز واحد + doxycycline 100 mg PO دو بار روزانه 10 روز. سن > 35: levofloxacin 500 mg PO روزانه 10 روز یا ofloxacin 300 mg PO دو بار روزانه 10 روز. علاوه: بالا نگه داشتن اسکروتوم، یخ، NSAID، اپیوئید و نرم‌کننده مدفوع. ارکیت: درمان اختصاصی، حمایتی، پیگیری اورولوژی.","section":"renal-genitourinary","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 55: Male Genital Problems, pp. 306–311"},"acute-prostatitis":{"id":"acute-prostatitis","variants":[{"id":"prostatitis-outpatient","o":{"L":[{"t":"Urinalysis and culture (often negative); testing for gonorrhea and chlamydia in patients with risk factors for sexually transmitted disease"}],"A":[{"t":"Ciprofloxacin 500 mg twice daily, or Levofloxacin 500 mg PO daily, or Ofloxacin 300 mg PO twice daily; all for 2 to 4 weeks"}],"T":[{"t":"Pain medicine as required","fl":[{"k":"note","v":"drug and dose not given in the book"}]}]},"name":"Acute prostatitis, stable","level":"III","imp":"Acute prostatitis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۵۰ ساله با دیزوری، درد پرینه و تب خفیف؛ پایدار.","why":"تشخیص بالینی؛ فلوروکینولون 2 تا 4 هفته."},{"id":"prostatitis-septic","o":{"L":[{"t":"Urinalysis and urine culture"}],"A":[{"t":"Piperacillin-tazobactam 3.375 to 4.5 g IV, or Cefotaxime with an aminoglycoside"}],"Co":[{"t":"Admission; urology"}]},"name":"Acute prostatitis, septic or immunocompromised","level":"II","imp":"Acute prostatitis with sepsis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مردی ۷۰ ساله دیابتی با تب، لرز، فشار 90/60 و تندرنس پروستات.","why":"سپسیس یا ایمنوساپرسیون نیاز به بستری و آنتی‌بیوتیک وریدی دارد."}],"ch":"55","name":"Acute prostatitis","name_fa":"پروستاتیت حاد","cc":["urinary-symptoms","genital-complaint","fever"],"keywords":"prostatitis, perineal pain, ciprofloxacin, levofloxacin, pyuria, پروستاتیت","status":"draft","features":["التهاب باکتریال پروستات: درد سوپراپوبیک/تناسلی/کمر/پرینه، مشکل ادرار، تکرر، دیزوری، درد حین انزال، تب و لرز","عوامل خطر: انسداد تحتانی مجاری ادراری، اپیدیدیمیت یا اورتریت، رابطه مقعدی محافظت‌نشده، فیموز، کاتتر دائم","E. coli در بیشتر موارد؛ Pseudomonas، Klebsiella، Enterobacter، Serratia یا Staphylococcus","معاینه: تندرنس پرینه، رکتوم و پروستات؛ تشخیص بالینی (UA و کشت اغلب منفی حتی بعد از ماساژ)"],"ddx":[{"n":"Sepsis from urinary source |","cm":1},{"n":"Epididymitis / urethritis |"},{"n":"Cystitis / pyelonephritis |"},{"n":"Prostatic abscess / urinary retention |"}],"redflags":["سپسیس، ایمنوساپرسیون، بدتر شدن با درمان سرپایی، احتباس ادرار"],"guide":"درمان: ciprofloxacin 500 mg دو بار روزانه یا levofloxacin 500 mg PO روزانه یا ofloxacin 300 mg PO دو بار روزانه؛ همه برای 2 تا 4 هفته؛ ضددرد در صورت نیاز. بستری فقط در سپسیس، ایمنوساپرسیون، بیماری‌های زمینه‌ای مهم یا بدتر شدن؛ آنگاه piperacillin-tazobactam 3.375 تا 4.5 g یا cefotaxime با آمینوگلیکوزید. در پرخطر برای STD: تست و درمان گنوره و کلامیدیا.","section":"renal-genitourinary","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 55: Male Genital Problems, pp. 306–311"},"scrotal-abscess-fournier":{"id":"scrotal-abscess-fournier","variants":[{"id":"scrotal-abscess-simple","o":{"T":[{"t":"Incision and drainage","fl":[{"k":"note","v":"no antibiotics required in immunocompetent patients"}]}],"Co":[{"t":"Urology consultation for definitive care of any complex abscess"}]},"name":"Simple scrotal wall (hair follicle) abscess","level":"III","imp":"Scrotal wall abscess","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۰ ساله سالم با آبسه کوچک فولیکولی روی اسکروتوم.","why":"برش و درناژ؛ بدون آنتی‌بیوتیک در ایمنوکمپتنت."},{"id":"fournier-gangrene","o":{"I":[{"t":"Ultrasound when abscess arises from intrascrotal contents; retrograde urethrography for a urethral source"}],"S":[{"t":"Aggressive fluid resuscitation with normal saline","fl":[{"k":"ci","v":"caution in heart failure / pulmonary edema"}]}],"A":[{"t":"Imipenem 1 g IV every 8 hours, or Meropenem 500 mg to 1 g IV every 8 hours (covers gram-positive, gram-negative and anaerobic organisms)"},{"t":"plus Vancomycin 1 g IV every 12 hours","if":"MRSA suspected"}],"T":[{"t":"Hyperbaric oxygen therapy if readily available"}],"Co":[{"t":"Early surgical consultation for surgical debridement"}]},"name":"Fournier gangrene","level":"I","imp":"Fournier gangrene","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مردی ۶۰ ساله دیابتی با درد پرینه، اریتم، کرپیتوس و فشار 85/50.","why":"عفونت نکروزان پلی‌میکروبیال؛ مایع تهاجمی، آنتی‌بیوتیک وسیع‌الطیف و دبریدمان فوری."}],"ch":"55","name":"Scrotal abscess and Fournier gangrene","name_fa":"آبسه اسکروتوم و گانگرن فورنیه","cc":["genital-complaint","fever"],"keywords":"scrotal abscess, Fournier gangrene, perineal necrotizing infection, imipenem, meropenem, vancomycin, hyperbaric oxygen, گانگرن فورنیه","status":"draft","features":["آبسه اسکروتوم: محدود به دیواره یا گسترش عفونت محتویات اسکروتوم (بیضه، اپیدیدیم، مجرای بولبار)","فولیکول مو: ساده؛ در شک به منشأ داخل اسکروتومی، سونوگرافی پاتولوژی بیضه/اپیدیدیم را نشان می‌دهد؛ اورتروگرافی رتروگراد برای منبع مجرا","Fournier: عفونت پلی‌میکروبیال بافت زیرجلدی پرینه؛ دیابتی‌ها و هر ایمنوساپرسیون پرخطر؛ تشخیص سریع برای جلوگیری از از دست رفتن وسیع بافت؛ درد اسکروتوم، رکتوم یا ژنیتال"],"ddx":[{"n":"Fournier gangrene (necrotizing infection) |","cm":1},{"n":"Epididymitis / orchitis abscess |"},{"n":"Urethral source infection |"},{"n":"Simple hair follicle abscess |"}],"redflags":["دیابتی یا ایمنوساپرس با درد اسکروتوم/رکتوم/ژنیتال، سیر سریع، سمیت"],"guide":"آبسه ساده فولیکول مو: برش و درناژ؛ در ایمنوکمپتنت آنتی‌بیوتیک لازم نیست. آبسه پیچیده: مشاوره اورولوژی. Fournier: مشاوره زود جراحی؛ پایه درمان: مایع تهاجمی نرمال سالین و آنتی‌بیوتیک وسیع‌الطیف پوشش‌دهنده گرم‌مثبت، گرم‌منفی و بی‌هوازی: imipenem 1 g IV هر 8 ساعت یا meropenem 500 mg تا 1 g IV هر 8 ساعت به‌علاوه vancomycin 1 g IV هر 12 ساعت اگر MRSA مطرح؛ اکسیژن هیپرباریک (در دسترس) و دبریدمان جراحی.","section":"renal-genitourinary","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 55: Male Genital Problems, pp. 306–311"},"penile-disorders":{"id":"penile-disorders","variants":[{"id":"penile-paraphimosis","o":{"T":[{"t":"Wrap the glans with 2 × 2-in. elastic bandages for 5 minutes to compress edema, then reduce the foreskin"},{"t":"Several puncture wounds with a small (22- to 25-gauge) needle to express glans edema fluid"},{"t":"Local anesthetic block of the penis if the patient cannot tolerate the discomfort"},{"t":"local infiltration of the constricting band with 1% plain lidocaine followed by superficial vertical incision of the band to decompress the glans and allow reduction","if":"arterial compromise suspected"}],"Co":[{"t":"Urology if reduction fails"}]},"name":"Paraphimosis","level":"II","imp":"Paraphimosis","cond":"Emergent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۶۰ ساله با کاتتر که پوست ختنه‌گاه را عقب برده و گلنس ادماتو و دردناک است.","why":"اورژانس واقعی اورولوژی؛ ادم تا ایسکمی و گانگرن؛ جا انداختن فوری."},{"id":"penile-priapism-fracture","o":{"I":[{"t":"Retrograde urethrography to assure urethral integrity","if":"penile fracture"},{"t":"Retrograde urethrogram and Doppler studies if indicated","if":"penile entrapment"}],"T":[{"t":"Corporal aspiration and instillation of an α-adrenergic antagonist (phenylephrine)","if":"priapism","fl":[{"k":"note","v":"dose not given in the book"}]}],"Co":[{"t":"Urologic consultation in all cases (even when the emergency physician provides stabilizing care)"}]},"name":"Priapism or penile fracture","level":"I","imp":"Priapism / penile fracture","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مردی ۳۵ ساله با نعوظ دردناک ۶ ساعته یا شکستگی آلت پس از مقاربت.","why":"پریاپیسم: آسپیراسیون و فنیل‌افرین؛ شکستگی: اورتروگرافی و جراحی؛ اورولوژی در همه موارد."},{"id":"penile-balanoposthitis-phimosis","o":{"L":[{"t":"Blood glucose (balanoposthitis can be the sole presenting sign of diabetes)"}],"T":[{"t":"Cleaning with mild soap and ensuring adequate dryness"},{"t":"Nystatin 100,000 U/g four times daily or Clotrimazole 1% cream twice daily"},{"t":"Fluconazole 150 mg single dose (oral azole), reevaluate at 7 days for repeat dosing"},{"t":"Hydrocortisone 1% cream for 4 to 6 weeks with daily preputial retraction; hemostatic dilation of the preputial ostium to relieve urinary retention until dorsal slit or circumcision","if":"phimosis"}],"A":[{"t":"Cephalexin 500 mg","if":"secondary bacterial infection","fl":[{"k":"note","v":"oral cephalosporin; frequency not given in the book"}]}],"Co":[{"t":"Urologic referral for reassessment and possible circumcision in recurrent cases"}]},"name":"Balanoposthitis / phimosis / Peyronie (outpatient)","level":"III","imp":"Balanoposthitis / phimosis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۴۵ ساله دیابتی با قرمزی، چرک و بوی بد زیر پوست ختنه‌گاه.","why":"درمان موضعی و ارزیابی دیابت؛ ارجاع در موارد راجعه."}],"ch":"55","name":"Penile disorders (balanoposthitis, phimosis, paraphimosis, entrapment, fracture, Peyronie, priapism)","name_fa":"اختلالات آلت (بالانوپوستیت، فیموز، پارافیموز، گیرافتادگی، شکستگی، پیرونی، پریاپیسم)","cc":["genital-complaint"],"keywords":"balanoposthitis, phimosis, paraphimosis, penile fracture, penile entrapment, Peyronie, priapism, phenylephrine, corporal aspiration, پارافیموز, پریاپیسم","status":"draft","features":["بالانوپوستیت: التهاب گلنس و پوست ختنه‌گاه؛ چرک، اکسکوریاسیون، بوی بد و تندرنس؛ می‌تواند اولین نشانه دیابت باشد","فیموز: ناتوانی در عقب بردن پوست ختنه‌گاه؛ فیزیولوژیک در پسران (کمتر از 10٪ در 3 سالگی)؛ پاتولوژیک: عفونت، بهداشت بد یا جای زخم","پارافیموز: ناتوانی در برگرداندن پوست ادماتو روی گلنس؛ اورژانس واقعی اورولوژی (ادم و احتقان وریدی، سپس ایسکمی شریانی و گانگرن)","گیرافتادگی آلت: اجسام دور آلت با مختل شدن عروق","شکستگی آلت: پارگی حاد تونیکا آلبوژینه؛ تورم، تغییر رنگ، تندرنس، صدای شکستن و از دست رفتن ناگهانی نعوظ حین مقاربت","پیرونی: انحنای پیشرونده دردناک، پلاک ضخیم روی ساقه پشتی؛ ED","پریاپیسم: نعوظ دردناک پاتولوژیک با احتباس ادرار، عفونت و ناتوانی جنسی"],"ddx":[{"n":"Paraphimosis (arterial compromise) |","cm":1},{"n":"Penile fracture with urethral injury |","cm":1},{"n":"Priapism |","cm":1},{"n":"Balanitis / candidiasis / diabetes |"},{"n":"Peyronie disease |"}],"redflags":["پارافیموز با شک به ایسکمی شریانی، پریاپیسم، شکستگی آلت با خون در مجرا"],"guide":"# بالانوپوستیت\nشست‌وی با صابون ملایم و خشک نگه‌داشتن، کرم ضدقارچ (nystatin 100000 U/g چهار بار روزانه یا clotrimazole 1٪ دو بار روزانه) و آزول خوراکی (fluconazole 150 mg دوز واحد؛ ارزیابی مجدد روز 7)؛ موارد راجعه: ارجاع اورولوژی برای ختنه؛ عفونت ثانویه: cephalexin 500 mg (سفالوسپورین خوراکی).\n# فیموز\nدیلاتاسیون هموستاتیک سوراخ پوست ختنه‌گاه برای رفع احتباس تا dorsal slit یا ختنه؛ استروئید موضعی (hydrocortisone 1٪ 4 تا 6 هفته) با عقب‌بردن روزانه.\n# پارافیموز\nبانداژ 2×2 inch الاستیک دور گلنس 5 دقیقه برای کاهش ادم؛ چند سوراخ با سوزن 22–25 gauge برای خروج مایع؛ بلوک موضعی آلت؛ در ایسکمی شریانی: تزریق lidocaine 1٪ ساده و برش عمودی سطحی باند.\n# گیرافتادگی\nفشردن، بریدن، سرد کردن آلت و احتمالاً جراحی؛ اورتروگرافی رتروگراد و دوپلر در صورت لزوم.\n# شکستگی\nاورتروگرافی رتروگراد برای سلامت مجرا؛ مشاوره اورولوژی.\n# پیرونی\nاطمینان‌بخشی و پیگیری اورولوژی.\n# پریاپیسم\nآسپیراسیون کورپوس و تزریق آگونیست α-آدرنرژیک (phenylephrine)؛ مشاوره اورولوژی همیشه.","section":"renal-genitourinary","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 55: Male Genital Problems, pp. 306–311"},"urethral-disorders":{"id":"urethral-disorders","variants":[{"id":"urethritis-std","o":{"L":[{"t":"First-void urine specimen (confirmation)"}],"A":[{"t":"Ceftriaxone 250 mg IM and Azithromycin 1 g PO"}]},"name":"Urethritis","level":"III","imp":"Urethritis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۲۴ ساله با ترشح چرکی از مجرا و دیزوری.","why":"تشخیص بالینی، درمان آمیزشی."},{"id":"urethral-stricture-foreign-body","o":{"I":[{"t":"Bedside ultrasonography for post-void residual (normal < 100 mL); retrograde urethrography to delineate stricture location and extent; radiography of the bladder and urethral areas for a foreign body"}],"T":[{"t":"Coude catheter (12-Fr after anesthetic lubricant, no more than three gentle attempts; 14- or 16-Fr Foley first)"},{"t":"Emergency suprapubic cystotomy (Seldinger technique) if needed"}],"Co":[{"t":"Urology consultation (urologic follow-up within 48 hours; endoscopy or open cystotomy for foreign body)"}]},"name":"Urethral stricture / urethral foreign body with retention","level":"II","imp":"Urethral stricture / foreign body","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مردی ۶۰ ساله با تنگی مجرا و احتباس ادرار؛ Foley 16 Fr عبور نمی‌کند.","why":"Coudé و حداکثر سه تلاش ملایم؛ سپس اورولوژی یا سیستوتومی."}],"ch":"55","name":"Urethritis, urethral stricture and urethral foreign body","name_fa":"اورتریت، تنگی مجرا و جسم خارجی مجرا","cc":["genital-complaint","urinary-symptoms"],"keywords":"urethritis, urethral stricture, Coude catheter, suprapubic cystotomy, urethral foreign body, ceftriaxone, azithromycin, اورتریت","status":"draft","features":["اورتریت: ترشح چرکی مجرا؛ تشخیص بالینی، تأیید با ادرار اول‌جریان؛ Chlamydia trachomatis و N. gonorrhoeae؛ گاهی Trichomonas، Ureaplasma، HSV","تنگی مجرا: شایع‌تر به‌علت STD؛ احتباس ادرار؛ باقیمانده پس از ادرار طبیعی < 100 mL (سونوگرافی)","اگر مثانه کاتتریزه نشد: تنگی، اسپاسم ارادی اسفنکتر خارجی، تنگی گردن مثانه یا BPH","جسم خارجی مجرا: ادرار خونی و ادرار آهسته دردناک؛ رادیوگرافی مثانه/مجرا"],"ddx":[{"n":"Urethral injury |","cm":1},{"n":"Epididymitis / prostatitis |"},{"n":"Urethral stricture / bladder neck contracture / BPH |"},{"n":"Voluntary external sphincter spasm |"}],"redflags":["شکست کاتتریزاسیون، احتباس، جسم خارجی با خون در مجرا"],"guide":"اورتریت: ceftriaxone 250 mg IM و azithromycin 1 g PO. تنگی: اگر Foley 14–16 Fr نرفت Coudé؛ اورتروگرافی رتروگراد؛ اسپاسم ارادی: آلت را عمودی نگه دار و تشویق به ریلکس کردن پرینه و تنفس آهسته. بعد از حداکثر سه تلاش ملایم با Coudé 12 Fr و مجرای آماده‌شده با ژل بی‌حسی: مشاوره اورولوژی؛ اورژانس: سیستوتومی سوپراپوبیک با تکنیک Seldinger؛ پیگیری ظرف 48 ساعت. جسم خارجی: اغلب اورولوژی (اندوسکوپی یا سیستوتومی باز)؛ ماساژ ملایم انتهای پروگزیمال قابل امتحان؛ اورتروگرافی یا اندوسکوپی برای تأیید سلامت مجرا.","section":"renal-genitourinary","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 55: Male Genital Problems, pp. 306–311"},"renal-colic-urolithiasis":{"id":"renal-colic-urolithiasis","variants":[{"id":"colic-uncomplicated","o":{"I":[{"t":"Noncontrast helical CT (low-dose protocol acceptable for stones > 3 mm and BMI > 30); ultrasound if CT is not advised (pregnant women, children); bedside ultrasound by ED physicians"},{"t":"KUB to follow stone progression once visualized on CT (outpatient)"}],"L":[{"t":"Urinalysis (hematuria and infection); serum renal function; pregnancy test in females of childbearing age"}],"S":[{"t":"@fluid","if":"vomiting or decreased oral intake with volume deficit","why":"corrects volume deficits only; not effective for pain control or stone passage","fl":[{"k":"ci","v":"avoid in CKD, AKI, heart failure"}]}],"T":[{"t":"Ketorolac 30 mg IVP","fl":[{"k":"renal","v":"caution in the elderly, bleeding tendencies and renal impairment"}]},{"t":"Morphine 5 mg IV or Hydromorphone 1 mg IV (titrated opioid)","fl":[{"k":"hi","v":""}]},{"t":"Metoclopramide 10 mg IV"},{"t":"Tamsulosin 0.4 mg daily up to 4 weeks, or Terazosin 5 to 10 mg daily, or Doxazosin 4 mg daily (medical expulsion therapy)"}],"Co":[{"t":"Urine strainer, oral analgesics and medical expulsive therapy; urologic or primary care follow-up within 7 days"}]},"name":"Uncomplicated renal colic (stone < 5 mm, controlled pain)","level":"III","imp":"Renal colic","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"مردی ۳۵ ساله با درد فلانک راست شدید و موجی، تهوع و هماچوری؛ بدون تب.","why":"تشخیص بالینی؛ CT یا سونو؛ NSAID و MET؛ سنگ کوچک با درد قابل کنترل: ترخیص با صافی."},{"id":"colic-complicated","o":{"I":[{"t":"Noncontrast helical CT; ultrasound for hydronephrosis"}],"L":[{"t":"Urinalysis, serum renal function, pregnancy test (females of childbearing age); urine and blood cultures","fl":[{"k":"note","v":"cultures not specifically stated in this chapter"}]}],"S":[{"t":"Correct volume deficits with crystalloid","fl":[{"k":"ci","v":"caution in heart failure / pulmonary edema; AKI"}]}],"A":[{"t":"Gentamicin or Tobramycin 1 mg/kg/dose every 8 hours and Ampicillin 1 to 2 g every 4 hours; or Piperacillin-tazobactam 3.375 g every 6 hours; or Cefepime 2 g every 8 hours; or Ticarcillin-clavulanic acid 3.1 g every 6 hours; or Ciprofloxacin 400 mg every 12 hours","fl":[{"k":"renal","v":"aminoglycosides"}]}],"T":[{"t":"Ketorolac 30 mg IVP ; Morphine 5 mg IV or Hydromorphone 1 mg IV","fl":[{"k":"renal","v":"avoid in renal impairment"},{"k":"hi","v":""}]},{"t":"Metoclopramide 10 mg IV"}],"Co":[{"t":"Emergent urologic consultation (complete obstruction with fever and/or urosepsis; solitary or transplanted kidney); admission, urgent decompression"}]},"name":"Renal colic with infection / obstruction / solitary kidney / AKI","level":"I","imp":"Renal colic with obstruction and possible urosepsis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"زنی ۴۵ ساله با درد فلانک، تب 39، لرز و فشار 90/55؛ سنگ انسدادی با هیدرونفروز.","why":"انسداد همراه تب/urosepsis یا کلیه منفرد نیاز به دکامپرسیون اورژانس و اورولوژی دارد."},{"id":"colic-infected-nonobstructing","o":{"I":[{"t":"Noncontrast helical CT or ultrasound"}],"L":[{"t":"Urinalysis"}],"A":[{"t":"Ciprofloxacin 500 mg twice a day for 10 to 14 days, or Levofloxacin 500 mg daily for 10 to 14 days, or Cefpodoxime 200 mg twice a day for 10 to 14 days (or other drugs with good local sensitivities)"}],"T":[{"t":"Ketorolac 30 mg IVP ; analgesia as above","fl":[{"k":"renal","v":"caution in renal impairment"}]}],"Co":[{"t":"Close follow-up is essential; urology"}]},"name":"Infected ureteral stone without significant obstruction, afebrile, no systemic illness","level":"II","imp":"Infected ureteral stone","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"مردی ۴۰ ساله با درد فلانک خفیف و پیوری؛ بدون تب.","why":"بدون انسداد/تب/بیماری سیستمیک: فلوروکینولون یا سفالوسپورین سرپایی با پیگیری نزدیک."}],"ch":"56","name":"Renal colic / urolithiasis","name_fa":"کولیک کلیوی / سنگ مجاری ادراری","cc":["flank-pain","abdominal-pain","urinary-symptoms"],"keywords":"renal colic, kidney stone, ureteral stone, nephrolithiasis, ketorolac, tamsulosin, noncontrast CT, hydronephrosis, urosepsis, solitary kidney, سنگ کلیه","status":"draft","features":["رها شدن سنگ در حالب: کولیک کلیوی؛ شایع‌تر در مردان 30 تا 50 ساله؛ عود 37٪ در سال اول؛ زیر 16 سال 7٪","شروع حاد درد شدید با تهوع، استفراغ، تعریق؛ بیمار مضطرب، بی‌قرار و ناتوان از ثابت ماندن؛ درد تیز و دوره‌ای از فلانک به‌سمت شکم و کشاله ران؛ سنگ انتهایی (75٪): درد قدامی یا سوپراپوبیک؛ سنگ مثانه: دیزوری متناوب و هماچوری ترمینال","کودکان: تا 30٪ فقط هماچوری بدون درد","تاکی‌کاردی و فشار بالا ثانویه به درد؛ تب با UTI همراه؛ هماچوری در 85٪","افتراق مهم: AAA و دیسکسیون آئورت؛ آپاندیسیت، ایسکمی مزانتر، کولسیستیت، حاملگی نابجا، torsion گناد، انفارکتوس کلیه، فتق گیرافتاده، اپیدیدیمیت، سالپنژیت، پیلونفریت، زوستر، عضلانی، نکروز پاپیلر (سیکل‌سل، دیابت، NSAID، عفونت)","CT بدون کنتراست: بالاترین حساسیت و ویژگی (حساسیت 94٪ تا 97٪؛ ویژگی 96٪ تا 99٪؛ PPV 96٪؛ NPV 93٪ تا 97٪)؛ CT کم‌دوز مشابه برای سنگ > 3 mm و BMI > 30","KUB: فقط 90٪ سنگ‌ها رادیواپک؛ حساسیت 29٪ تا 58٪؛ برای پیگیری سنگ دیده‌شده در CT؛ IVP کم‌کاربرد","سونوگرافی (حاملگی و کودکان): هیدرونفروز و سنگ بزرگ؛ حساسیت 63٪ تا 85٪؛ برای سنگ < 5 mm یا میانی حالب ضعیف؛ 90٪ برای > 6 mm؛ مثبت کاذب با مثانه پر، کیست یا بولوس سریع کریستالوئید"],"ddx":[{"n":"Abdominal aortic aneurysm / aortic dissection |","cm":1},{"n":"Ectopic pregnancy / ovarian torsion / testicular torsion |","cm":1},{"n":"Obstructing stone with infection (urosepsis) |","cm":1},{"n":"Appendicitis / mesenteric ischemia / cholecystitis |"},{"n":"Pyelonephritis / renal infarction |"},{"n":"Musculoskeletal strain / herpes zoster / papillary necrosis |"}],"redflags":["تب با انسداد (اورولوژی اورژانس)، کلیه منفرد یا پیوندی، نارسایی حاد کلیه، استفراغ/درد مقاوم، سن بالا با درد فلانک و فشار پایین (AAA)"],"guide":"# دارو\n- ضددرد: NSAID تزریقی انتخاب اول؛ ketorolac 30 mg IVP؛ احتیاط در سالمند، دیاتز خونریزی و نارسایی کلیه؛ اپیوئید تیتره (morphine 5 mg IV یا hydromorphone 1 mg IV) با احتیاط در سالمند، کودک و حاملگی.\n- مایع وریدی: فقط برای اصلاح کمبود حجم ناشی از استفراغ/کم‌خوری؛ در کنترل درد یا دفع سنگ ثابت نشده.\n- ضدتهوع: metoclopramide 10 mg IV (تنها ضدتهوع مطالعه‌شده در کولیک).\n- درمان دفعی (MET): α-blocker: tamsulosin 0.4 mg روزانه تا 4 هفته، terazosin 5 تا 10 mg روزانه، doxazosin 4 mg روزانه؛ بهبود 2 تا 6 روز در زمان دفع؛ استروئید و CCB توصیه نمی‌شود.\n- آنتی‌بیوتیک اگر UA عفونت: بر اساس مقاومت محلی گرم‌منفی؛ سنگ عفونی بدون انسداد قابل‌توجه، تب یا بیماری سیستمیک: ciprofloxacin 500 mg دو بار روزانه 10 تا 14 روز، levofloxacin 500 mg روزانه 10 تا 14 روز یا cefpodoxime 200 mg دو بار روزانه 10 تا 14 روز؛ بیمار پیچیده: بستری و آنتی‌بیوتیک وریدی (gentamicin یا tobramycin 1 mg/kg هر 8 ساعت و ampicillin 1 تا 2 g هر 4 ساعت؛ piperacillin-tazobactam 3.375 g هر 6 ساعت؛ cefepime 2 g هر 8 ساعت؛ ticarcillin-clavulanic acid 3.1 g هر 6 ساعت؛ ciprofloxacin 400 mg هر 12 ساعت).\n# ترخیص\nسنگ کوچک < 5 mm، یک‌طرفه، بدون عفونت پیچیده و درد قابل کنترل با خوراکی: با صافی ادرار، ضددرد خوراکی و MET، پیگیری اورولوژی یا پزشک عمومی ظرف 7 روز. سنگ 5–6 mm: 7 تا 30 روز. بازگشت: تب، استفراغ ادامه‌دار، درد غیرقابل کنترل.\n# بستری\nمطلق: درد یا استفراغ مقاوم، urosepsis*، کلیه منفرد/پیوندی با انسداد*، نارسایی حاد کلیه، بحران هیپرکلسمیک؛ نسبی: تب، کلیه منفرد/پیوندی بدون انسداد، انسداد با نشانه عفونت، extravasation، بیماری زمینه‌ای مهم/سن بالا، سنگ بزرگ بالای لبه لگن. (* دکامپرسیون اورژانس).\nاورولوژی اورژانس: انسداد کامل با تب/urosepsis و کلیه منفرد یا پیوندی؛ سنگ > 5 mm، نارسایی کلیه، بیماری شدید، extravasation، پاپیلای کنده‌شده، UTI یا شکست درمان سرپایی: هماهنگی دیسپوزیشن با اورولوژی.","pearls":["در سالمند با درد فلانک و فشار پایین اول AAA را رد کن.","در حاملگی و کودک سونوگرافی به‌جای CT."],"section":"renal-genitourinary","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 56: Urologic Stone Disease, pp. 312–315"},"urinary-catheter-complications":{"id":"urinary-catheter-complications","variants":[{"id":"catheter-uti-mild","o":{"L":[{"t":"Urine microscopy and urine culture (add blood cultures if septic or immunocompromised)"}],"A":[{"t":"Ciprofloxacin 500 mg twice a day, or Levofloxacin 500 mg once a day, or Cefpodoxime 200 mg twice a day (7 days if prompt resolution of symptoms; 10 to 14 days if delayed response); tailor to local bacterial sensitivities"}],"T":[{"t":"Remove the urinary catheter if clinically feasible or replace the catheter if it is > 7 days old"}],"Co":[{"t":"Admission frequently required for catheter-associated pyelonephritis"}]},"name":"Catheter-associated UTI, mild symptoms","level":"III","imp":"Catheter-associated UTI","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۷۵ ساله با کاتتر دائم، تب خفیف و ادرار بدبو.","why":"CA-UTI با علائم خفیف: درمان تجربی و تعویض/برداشتن کاتتر."},{"id":"catheter-balloon-nondeflation","o":{"T":[{"t":"Cut the plastic catheter valve just proximal to the inflation port and insert a flexible guide wire to expand the channel and deflate the balloon"},{"t":"If unsuccessful, insert a 22-G central venous catheter over the guide wire; once the tip enters the balloon, remove the guide wire and deflate the balloon"},{"t":"If balloon persists, instill 10 cc of mineral oil through the CVC and wait 15 minutes to dissolve the balloon (may be repeated)"}],"Co":[{"t":"Urologist to remove the catheter if these methods fail"}]},"name":"Nondeflation of Foley retention balloon","level":"III","imp":"Foley retention balloon will not deflate","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۶۰ ساله که بالون فولی او خالی نمی‌شود.","why":"تکنیک‌های پلکانی با گایدوایر، CVC و روغن معدنی."}],"ch":"57","name":"Catheter-associated UTI and Foley balloon that will not deflate","name_fa":"عفونت ادراری وابسته به کاتتر و باز نشدن بالون فولی","cc":["urinary-symptoms","fever"],"keywords":"CA-UTI, catheter-associated urinary tract infection, Foley balloon nondeflation, mineral oil, guide wire, ciprofloxacin, levofloxacin, cefpodoxime, عفونت کاتتر","status":"draft","features":["CA-UTI: علت بسیار شایع عفونت بیمارستانی؛ تب، لرز، تغییر هوشیاری، بی‌حالی، درد فلانک، CVA tenderness، هماچوری حاد، ناراحتی لگن؛ بعد از خروج کاتتر: دیزوری، فوریت/تکرر، درد سوپراپوبیک","آسیب نخاعی: افزایش اسپاستیسیته، دیس‌رفلکسی اتونوم و احساس ناخوشی","پیلونفریت شایع‌ترین عارضه (وقتی تب)؛ پروستاتیت، اپیدیدیمیت و آبسه اسکروتوم","باکتریوری بدون علامت در کاتتر کوتاه‌مدت درمان نمی‌شود مگر حاملگی یا بلافاصله بعد از پروسیجر اورولوژیک","پیوری در همه با کاتتر طولانی (> 1 ماه) وجود دارد؛ بدون علامت نشانه عفونت نیست؛ هماچوری شاخص بهتر","بالون فولی که خالی نمی‌شود مانع خروج کاتتر است"],"ddx":[{"n":"Urosepsis / pyelonephritis |","cm":1},{"n":"Prostatitis / epididymitis / scrotal abscess |"},{"n":"Urinary obstruction (catheter blockage) |"},{"n":"Autonomic dysreflexia (spinal cord injury) |"}],"redflags":["سپسیس، ایمنوساپرسیون، تب با لرز و افت فشار"],"guide":"تشخیص بالینی با میکروسکوپی ادرار؛ کشت ادرار؛ کشت خون اگر سپتیک یا ایمنوساپرس؛ سونوگرافی برای انسداد. کاتتر را در صورت امکان بردار یا اگر > 7 روز است عوض کن. علائم خفیف: ciprofloxacin 500 mg دو بار روزانه، levofloxacin 500 mg روزانه یا cefpodoxime 200 mg دو بار روزانه؛ تنظیم بر اساس حساسیت محلی؛ 7 روز در پاسخ سریع و 10 تا 14 روز در پاسخ دیررس. پیلونفریت وابسته به کاتتر: اغلب بستری.\nبالون که خالی نمی‌شود: دریچه پلاستیکی را درست پروگزیمال به پورت باد کردن ببر و گایدوایر انعطاف‌پذیر وارد کن تا کانال باز شود؛ در شکست: CVC 22-G روی گایدوایر؛ وقتی نوک وارد بالون شد گایدوایر را بردار و بالون را خالی کن؛ اگر ادامه یافت 10 cc روغن معدنی از CVC بریز و 15 دقیقه صبر کن (قابل تکرار)؛ در شکست: اورولوژی.","pearls":["پیوری بدون علامت در کاتتر طولانی‌مدت عفونت نیست."],"section":"renal-genitourinary","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 57: Complications of Urologic Procedures and Devices, pp. 316–318"},"urologic-device-complications":{"id":"urologic-device-complications","variants":[{"id":"device-hemorrhage-hematoma","o":{"I":[{"t":"CT scan if a severe injury is suspected; renal ultrasound if simple obstruction suspected"}],"L":[{"t":"Hemoglobin, hematocrit, renal function studies, urinalysis; platelet count and coagulation studies if coagulopathy is suspected"}],"S":[{"t":"IV fluid resuscitation and blood transfusion in severe cases"}],"T":[{"t":"Mild nephrostomy bleeding: irrigate the nephrostomy tube to clear clots"},{"t":"Antiemetics and analgesics","fl":[{"k":"note","v":"drugs and doses not given in the book"}]},{"t":"irrigate the bladder and transfuse appropriately","if":"severe gross hematuria, syncope or hypotension with a stent"}],"Co":[{"t":"Emergent urology consultation (bleeding that fails to resolve may be a vascular injury; surgical intervention may be indicated)"}]},"name":"Hemorrhage / hematoma after nephrostomy, lithotripsy or eroding stent","level":"I","imp":"Hemorrhage after urologic procedure / device","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مردی ۵۵ ساله ۲ روز بعد از لیتوتریپسی با سنکوپ، هماتوم فلانک و افت هموگلوبین.","why":"هماتوم اطراف کلیه نشانه عارضه جدی؛ احیا و CT و اورولوژی زود."},{"id":"device-infection-obstruction","o":{"I":[{"t":"Imaging to verify stent position (abdominal series, ultrasound, CT); CT for dislodgment, tube blockage and residual stone fragments (nephrostomy)"}],"L":[{"t":"Urinalysis and urine culture; blood cultures if pyelonephritis or urosepsis suspected; urine and wound drainage culture (nephrostomy)"}],"A":[{"t":"outpatient antibiotics in consultation with a urologist","if":"simple infection","fl":[{"k":"note","v":"drug and dose not given in the book"}]},{"t":"IV antibiotics (broad-spectrum for prosthesis)","if":"pyelonephritis or urosepsis suspected; artificial sphincter infection; penile prosthesis infection","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"T":[{"t":"Never introduce a urinary drainage catheter through an artificial urinary sphincter"}],"Co":[{"t":"Urology (device removal for infected penile prosthesis; stent removal not always necessary)"}]},"name":"Infection / obstruction related to nephrostomy, stent, sphincter or prosthesis","level":"II","imp":"Infection or malfunction of urologic device","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"زنی ۶۰ ساله با استنت حالب و تب، درد فلانک و علائم تحریکی مثانه.","why":"عفونت ساده سرپایی با مشورت اورولوژی؛ پیلونفریت/urosepsis: کشت، آنتی‌بیوتیک وریدی و تصویربرداری."},{"id":"device-priapism-injection","o":{"T":[{"t":"Corporal aspiration and instillation of an α-adrenergic antagonist (phenylephrine)","fl":[{"k":"note","v":"dose not given in the book"}]}],"Co":[{"t":"Emergent urologic consultation"}]},"name":"Priapism after erectile dysfunction injection","level":"I","imp":"Priapism from erectile dysfunction injection","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مردی ۵۰ ساله پس از تزریق داخل‌کورپوس با نعوظ دردناک ۵ ساعته.","why":"پریاپیسم ناشی از تزریق نیاز به مشاوره اورولوژی اورژانس دارد."}],"ch":"57","name":"Complications of nephrostomy, lithotripsy, ureteral stents, artificial sphincter and ED devices","name_fa":"عوارض نفروستومی، لیتوتریپسی، استنت حالب، اسفنکتر مصنوعی و وسایل نعوظ","cc":["flank-pain","urinary-symptoms","genital-complaint"],"keywords":"percutaneous nephrostomy, lithotripsy, ureteral stent, artificial urinary sphincter, penile prosthesis, priapism, retroperitoneal hematoma, vascular fistula, عوارض استنت","status":"draft","features":["نفروستومی از راه پوست: خونریزی (کنترل هموگلوبین، هماتوکریت، کراتینین؛ پلاکت/انعقاد در شک)؛ عفونت (باکتریوری، پیلونفریت، آبسه کلیه، urosepsis)؛ جابه‌جایی کاتتر، انسداد لوله، باقیمانده قطعات سنگ","لیتوتریپسی: درد شکم/فلانک، هماچوری ماکروسکوپیک، اکیموز، انسداد حالب؛ جدی: پارگی/سوراخ شدن عضو، عفونت (پیلونفریت، urosepsis، آبسه psoas)، آسیب عروقی، پانکراتیت؛ هیپوتانسیون، سنکوپ، هماتوم فلانک، افت هموگلوبین و درد شدید = هماتوم اطراف کلیه/کلیه","استنت حالب: عفونت؛ دیررس: درد جدید شکم، درد شدید فلانک، تب، علائم تحریکی مثانه یا هماچوری شدید (مهاجرت، انسداد، عفونت)؛ کم‌خونی جدید بدون هماچوری: هماتوم رتروپریتوان؛ هماچوری شدید، سنکوپ یا هیپوتانسیون: فیستول عروقی ناشی از فرسایش","اسفنکتر مصنوعی ادراری: عفونت زودرس فلور پوست؛ دیررس گرم‌منفی؛ هرگز کاتتر از میان اسفنکتر مصنوعی رد نکن","وسایل ED: تزریق → پریاپیسم (اورولوژی اورژانس)؛ پمپ خلأ: درد، نکروز پوست و عفونت؛ پروتز: عفونت، فرسایش، مهاجرت"],"ddx":[{"n":"Perinephric / renal / retroperitoneal hematoma |","cm":1},{"n":"Urosepsis |","cm":1},{"n":"Vascular fistulization from eroding stent |","cm":1},{"n":"Stent migration / obstruction |"},{"n":"Priapism from injection |"}],"redflags":["هیپوتانسیون، سنکوپ، هماتوم فلانک، افت هموگلوبین، هماچوری شدید، سپسیس"],"guide":"# نفروستومی\nخونریزی خفیف: شست‌وی لوله؛ عدم رفع → آسیب عروقی و اورولوژی اورژانس؛ شدید: مایع و خون. عفونت: کشت ادرار و ترشح زخم و آنتی‌بیوتیک پس از مشورت اورولوژی. جابه‌جایی/انسداد/قطعات سنگ: CT و اورولوژی.\n# لیتوتریپسی\nحمایتی با مایع، ضدتهوع و ضددرد؛ شمارش خون، کراتینین، UA؛ کشت و آنتی‌بیوتیک در صورت لزوم؛ سونوگرافی کلیه در انسداد ساده، CT در آسیب شدیدتر؛ اورولوژی زود.\n# استنت\nUA و کشت؛ عفونت ساده: آنتی‌بیوتیک سرپایی با مشورت اورولوژی؛ پیلونفریت/urosepsis: کشت، آنتی‌بیوتیک وریدی، تصویربرداری (سری شکمی، سونو، CT) و اورولوژی؛ فیستول عروقی: احیا، آزمایش، شست‌وی مثانه، ترانسفوزیون، اورولوژی فوری.\n# اسفنکتر و وسایل\nUA، آزمایش، کشت، تصویربرداری و آنتی‌بیوتیک وریدی، اورولوژی؛ پروتز عفونی: آنتی‌بیوتیک وسیع‌الطیف وریدی و اورولوژی برای برداشتن.","section":"renal-genitourinary","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 57: Complications of Urologic Procedures and Devices, pp. 316–318"}});
